return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-06 01:48+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'வூகாமர்ஸ்','Go to Plugin Search' => 'செருகுநிரல் தேடலுக்குச் செல்லவும்.','Activate %s' => '%s ஐ செயல்படுத்து','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> க்கு <strong>%2$s</strong> நிறுவப்பட்டு செயல்படுத்தப்பட வேண்டும். <a href="%4$s">%3$s</a>','Enter your code here' => 'உங்கள் குறியீட்டை இங்கே உள்ளிடவும்.','Add %s' => '%s ஐச் சேர்','Remove' => 'அகற்று','Order number and receipt will be sent to this email address.' => 'ஆர்டர் எண் மற்றும் ரசீது இந்த மின்னஞ்சல் முகவரிக்கு அனுப்பப்படும்.','Apartment, unit, building, floor, etc.' => 'அபார்ட்மெண்ட், யூனிட், கட்டிடம், தளம், முதலியன.','Shipping phone' => 'ஷிப்பிங் தொலைபேசி எண்','Only used for shipping-related questions.' => 'கப்பல் போக்குவரத்து தொடர்பான கேள்விகளுக்கு மட்டுமே பயன்படுத்தப்படுகிறது.','Single step' => 'ஒற்றை படி','Click to go to the order summary' => 'ஆர்டர் சுருக்கத்திற்குச் செல்ல கிளிக் செய்யவும்.','Cart total:' => 'மொத்த கூடை:','Proceed to %s' => '%s க்குச் செல்','Proceed to contact' => 'தொடர்புக்குச் செல்லவும்','Proceed to shipping' => 'அனுப்புவதற்குத் தொடரவும்','Proceed to billing' => 'பில்லிங்கிற்குச் செல்லவும்','Proceed to payment' => 'பணம் செலுத்தத் தொடங்குங்கள்','Shipping method' => 'அனுப்பும் முறை','Additional notes' => 'கூடுதல் குறிப்புகள்','Payment method' => 'கட்டணம் செலுத்தும் முறை','Step %1$s of %2$s' => '%2$s இல் %1$s படி','Change: %s' => 'மாற்றம்: %s','Not selected yet.' => 'இன்னும் தேர்ந்தெடுக்கப்படவில்லை.','Same as shipping address' => 'ஷிப்பிங் முகவரியைப் போலவே','Same as billing address' => 'பில்லிங் முகவரியைப் போலவே','Order summary' => 'ஆர்டர் சுருக்கம்','Edit cart' => 'கூடையைத் திருத்து','Did you mean %s?' => 'நீங்க %s-ஐயா சொன்னீங்க?','Change email address to: {suggestion-value}' => 'மின்னஞ்சல் முகவரியை {suggestion-value} ஆக மாற்றவும்.','This is a required field.' => 'இது அவசியமான புலம்.','This is not a valid email address.' => 'இது செல்லுபடியாகும் மின்னஞ்சல் முகவரி அல்ல.','This field does not match the related field value.' => 'இந்தப் புலம் தொடர்புடைய புல மதிப்புடன் பொருந்தவில்லை.','The CPF number "{cpf_number}" is invalid.' => '&quot;{cpf_number}&quot; என்ற CPF எண் தவறானது.','The CNPJ number "{cnpj_number}" is invalid.' => 'CNPJ எண் &quot;{cnpj_number}&quot; தவறானது.','(Required)' => '(தேவை)','Checkout Header - Desktop' => 'செக்அவுட் தலைப்பு - டெஸ்க்டாப்','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'பெரிய திரைகளுக்கான செக்அவுட் தலைப்பில் விட்ஜெட்களைக் காண்பி. செருகுநிரலின் செக்அவுட் தலைப்பைப் பயன்படுத்தினால் மட்டுமே காண்பிக்கப்படும்.','Checkout Header - Mobile' => 'செக்அவுட் தலைப்பு - மொபைல்','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'மொபைல் சாதனங்களுக்கான செக்அவுட் தலைப்புக்குக் கீழே விட்ஜெட்களைக் காண்பி. செருகுநிரலின் செக்அவுட் தலைப்பு பயன்படுத்தினால் மட்டுமே காண்பிக்கப்படும்.','Checkout Sidebar' => 'பக்கப்பட்டியைப் பாருங்கள்','Display widgets on the checkout sidebar after the order summary.' => 'ஆர்டர் சுருக்கத்திற்குப் பிறகு செக்அவுட் பக்கப்பட்டியில் விட்ஜெட்களைக் காண்பி.','Checkout Order Summary' => 'செக்அவுட் ஆர்டர் சுருக்கம்','Display widgets inside the order summary at the checkout page.' => 'செக்அவுட் பக்கத்தில் ஆர்டர் சுருக்கத்திற்குள் விட்ஜெட்களைக் காண்பி.','Checkout Below Place Order' => 'இட வரிசைக்கு கீழே செக்அவுட் செய்யவும்','Display widgets below the place order button at the checkout page.' => 'செக்அவுட் பக்கத்தில் இட வரிசை பொத்தானுக்குக் கீழே விட்ஜெட்களைக் காண்பி.','Checkout Footer' => 'செக்அவுட் அடிக்குறிப்பு','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'செக்அவுட் அடிக்குறிப்பில் விட்ஜெட்களைக் காண்பி. செருகுநிரலின் செக்அவுட் அடிக்குறிப்பைப் பயன்படுத்தினால் மட்டுமே காண்பிக்கப்படும்.','Classic' => 'கிளாசிக்','Boxed' => 'பெட்டி','Split' => 'பிரி','Minimalist' => 'மினிமலிஸ்ட்','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'CodeRockz வழங்கும் திரவ செக்அவுட் மற்றும் டெலிவரி தேதி செருகுநிரல்கள்','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>நீங்கள் CodeRockz இன் WooCommerce (இலவசம் மற்றும் PRO) க்கான டெலிவரி &amp; பிக்அப் தேதி நேரம் செருகுநிரல்களைப் பயன்படுத்துவதை நாங்கள் கண்டறிந்துள்ளோம். இந்த செருகுநிரல்களுடனான ஒருங்கிணைப்பு Fluid Checkout PRO க்கு நகர்த்தப்பட்டுள்ளது.</p>','Upgrade to PRO' => 'PRO க்கு மேம்படுத்து','Fluid Checkout database updated successfully' => 'திரவ செக்அவுட் தரவுத்தளம் வெற்றிகரமாக புதுப்பிக்கப்பட்டது.','The database changes where applied successfully.' => 'வெற்றிகரமாகப் பயன்படுத்தப்படும் இடத்தில் தரவுத்தளம் மாறுகிறது.','Dismiss' => 'நிராகரி','Fluid Checkout database update' => 'திரவ செக்அவுட் தரவுத்தள புதுப்பிப்பு','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'தரவுத்தளத்தில் சில மாற்றங்கள் தேவை. எந்தவொரு புதுப்பிப்பையும் போலவே, <strong>தொடர்வதற்கு முன் உங்கள் வலைத்தளத்தின் முழு காப்புப்பிரதியை எடுக்க</strong> பரிந்துரைக்கிறோம்.','Update database' => 'தரவுத்தளத்தைப் புதுப்பிக்கவும்','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'திரவ செக்அவுட், Divi Builder செக்அவுட் தளவமைப்புடன் இணக்கமாக இல்லை.','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Fluid Checkout வேலை செய்ய கிளாசிக் WooCommerce ஷார்ட்கோட் அடிப்படையிலான செக்அவுட் படிவம் தேவை. செக்அவுட் பக்கத்தின் தோற்றத்தையும் உணர்வையும் தனிப்பயனாக்க Divi Builder ஐப் பயன்படுத்தும் போது, செக்அவுட் பக்கத்தின் ஒவ்வொரு பகுதிக்கும் கிளாசிக் ஷார்ட்கோடுகள் Divi Builder இலிருந்து தனிப்பயன் விட்ஜெட்களால் மாற்றப்படும். இந்த தனிப்பயன் விட்ஜெட்டுகள் Fluid Checkout உடன் இணக்கமாக இல்லை.</p><p> Divi Builder விட்ஜெட்களுக்குப் பதிலாக <code>[woocommerce_checkout]</code> என்ற சுருக்குக்குறியீட்டைக் கொண்ட உரை விட்ஜெட்டைப் பயன்படுத்தி உங்கள் செக்அவுட் பக்கத்தைத் திருத்தவும்.</p>','Edit the checkout page' => 'செக்அவுட் பக்கத்தைத் திருத்தவும்','Read the documentation.' => 'ஆவணங்களைப் படியுங்கள்.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'திரவ செக்அவுட்டைப் பயன்படுத்தும் போது ஜெர்மன்மயமாக்கப்பட்ட PRO பலபடி செக்அவுட் அம்சத்தை முடக்க வேண்டும்.','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Fluid Checkout-ஐப் பயன்படுத்தும் போது, Germanized PRO plugin-இன் multistep அம்சம் தேவையற்றதாகி, <strong>புதிய ஆர்டர்களைச் செயல்படுத்தும்போது முக்கியமான பிழைகளை</strong> ஏற்படுத்தக்கூடும். plugin அமைப்புகளில் Germanized PRO multistep checkout அம்சத்தை முடக்கவும்.','Go to Germanized settings' => 'ஜெர்மன்மயமாக்கப்பட்ட அமைப்புகளுக்குச் செல்லவும்.','Thanks for choosing Fluid Checkout!' => 'திரவ செக்அவுட்டைத் தேர்ந்தெடுத்ததற்கு நன்றி!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'நீங்க கொஞ்ச நாளா இந்த ப்ளக் இன் யூஸ் பண்ணிட்டு இருக்கீங்க. இதுவரைக்கும் உங்களுக்கு இது எப்படிப் பிடிச்சிருக்கு?<br> தயவுசெய்து எங்களுக்கு ஒரு விரைவான மதிப்பீட்டை வழங்குங்கள், ஒவ்வொரு பின்னூட்டத்திற்கும் நாங்கள் நன்றி கூறுகிறோம், மேலும் இது செருகுநிரலை தொடர்ந்து மேம்படுத்த எங்களை ஊக்குவிக்கிறது :)','Rate the plugin' => 'செருகுநிரலை மதிப்பிடவும்.','I need help!' => 'எனக்கு உதவி தேவை!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Quadlayers வழங்கும் WooCommerce Checkout Manager இன் சில அம்சங்கள், Fluid Checkout உடன் பயன்படுத்தும் போது எதிர்பார்த்தபடி வேலை செய்யாமல் போகலாம். மேலும் தகவல் மற்றும் மாற்று தீர்வுகளுக்கு <a href="%s">எங்கள் ஆவணங்களைப்</a> படியுங்கள்.','Read documentation' => 'ஆவணங்களைப் படியுங்கள்','Don\'t show this again' => 'இதை மீண்டும் காட்டாதே','Fluid Checkout PRO' => 'திரவ செக்அவுட் புரோ','More design templates' => 'மேலும் வடிவமைப்பு வார்ப்புருக்கள்','Optimized cart page' => 'மேம்படுத்தப்பட்ட வண்டி பக்கம்','Optimized order received / thank you page' => 'மேம்படுத்தப்பட்ட ஆர்டர் பெறப்பட்டது / நன்றி பக்கம்','Edit cart contents at checkout page' => 'செக்அவுட் பக்கத்தில் கூடை உள்ளடக்கங்களைத் திருத்தவும்.','Account matching / user matching' => 'கணக்கு பொருத்தம் / பயனர் பொருத்தம்','Trust symbols on the cart and thank you pages' => 'வண்டியிலும் நன்றி பக்கங்களிலும் உள்ள சின்னங்களை நம்புங்கள்.','More positions for the coupon code on the checkout page' => 'செக் அவுட் பக்கத்தில் கூப்பன் குறியீட்டிற்கான கூடுதல் நிலைகள்','International phone numbers' => 'சர்வதேச தொலைபேசி எண்கள்','Gift messages and packing slips' => 'பரிசுச் செய்திகளும் பேக்கிங் சீட்டுகளும்','Local pickup and in-store collection' => 'உள்ளூர் பிக்அப் மற்றும் கடையில் சேகரிப்பு','EU-VAT Assistant' => 'EU-VAT உதவியாளர்','I already have it – Hide this offer' => 'எனக்கு ஏற்கனவே இது உள்ளது - இந்த சலுகையை மறை.','Activated' => 'செயல்படுத்தப்பட்டது','Address book' => 'முகவரி புத்தகம்','Select an image' => 'ஒரு படத்தைத் தேர்ந்தெடுக்கவும்','Cart layout' => 'வண்டி அமைப்பு','Cart optimizations' => 'வண்டி மேம்படுத்தல்கள்','Enable cart page optimizations' => 'கார்ட் பக்க மேம்படுத்தல்களை இயக்கு','Header and footer template' => 'தலைப்பு மற்றும் அடிக்குறிப்பு டெம்ப்ளேட்','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'கவனச்சிதறல் இல்லாத பக்க தலைப்பு மற்றும் அடிக்குறிப்பைப் பயன்படுத்துவதா அல்லது தற்போது செயலில் உள்ள கருப்பொருளின் தலைப்பு மற்றும் அடிக்குறிப்பைத் தக்கவைத்துக்கொள்வதா என்பதைக் கட்டுப்படுத்துகிறது.','Distraction free header and footer' => 'கவனச்சிதறல் இல்லாத தலைப்பு மற்றும் அடிக்குறிப்பு','Theme\'s header and footer' => 'தீமின் தலைப்பு மற்றும் அடிக்குறிப்பு','Cart elements' => 'கூடை கூறுகள்','Make the order summary stay visible on the cart page while scrolling' => 'ஸ்க்ரோல் செய்யும் போது ஆர்டர் சுருக்கம் கார்ட் பக்கத்தில் தெரியும்படி வைக்கவும்.','Coupon codes' => 'கூப்பன் குறியீடுகள்','Hidden' => 'மறைக்கப்பட்டது','Before the cart items section' => 'கூடை பொருட்கள் பிரிவுக்கு முன்','Inside the cart items section' => 'வண்டி பொருட்கள் பிரிவின் உள்ளே','After the cart items section' => 'கூடை பொருட்கள் பிரிவுக்குப் பிறகு','Before the shipping section' => 'கப்பல் பிரிவுக்கு முன்','After the shipping section' => 'கப்பல் பிரிவுக்குப் பிறகு','Before the order summary' => 'ஆர்டர் சுருக்கத்திற்கு முன்','Inside the order summary' => 'ஆர்டர் சுருக்கத்தின் உள்ளே','Before the order totals' => 'ஆர்டர் மொத்தமாக வருவதற்கு முன்பு','After the order totals' => 'ஆர்டர் மொத்தத்திற்குப் பிறகு','After the order summary' => 'ஆர்டர் சுருக்கத்திற்குப் பிறகு','Shipping' => 'கப்பல் போக்குவரத்து','Select position where to display the shipping costs and calculator on the cart page.' => 'வண்டி பக்கத்தில் ஷிப்பிங் செலவுகள் மற்றும் கால்குலேட்டரைக் காண்பிக்க வேண்டிய இடத்தைத் தேர்ந்தெடுக்கவும்.','Display as a cart section' => 'கூடைப் பிரிவாகக் காட்டு','Cross-sells' => 'குறுக்கு விற்பனைகள்','Select position where to display the cross-sells section on the cart page.' => 'வண்டி பக்கத்தில் குறுக்கு விற்பனைப் பிரிவைக் காண்பிக்க வேண்டிய இடத்தைத் தேர்ந்தெடுக்கவும்.','Before the cart actions' => 'வண்டி நடவடிக்கைகளுக்கு முன்','After the cart actions' => 'வண்டி நடவடிக்கைகளுக்குப் பிறகு','Layout of cross-sell items on the cart page.' => 'வண்டி பக்கத்தில் குறுக்கு விற்பனை பொருட்களின் தளவமைப்பு.','Optimized horizontal cross-sells layout' => 'உகந்த கிடைமட்ட குறுக்கு விற்பனை தளவமைப்பு','Theme\'s cross-sells layout' => 'கருப்பொருளின் குறுக்கு விற்பனை தளவமைப்பு','Number of cross-sell items to display on the cart page' => 'கூடை பக்கத்தில் காண்பிக்க வேண்டிய குறுக்கு விற்பனை பொருட்களின் எண்ணிக்கை.','Add widget areas to the cart page' => 'வண்டிப் பக்கத்தில் விட்ஜெட் பகுதிகளைச் சேர்க்கவும்.','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'இந்த விட்ஜெட் பகுதிகள் கார்ட் பக்கத்தில் நம்பிக்கை சின்னங்கள் மற்றும் நம்பிக்கை பேட்ஜ்களைச் சேர்க்கப் பயன்படுகின்றன.','Checkout' => 'சரிபார்','Checkout layout' => 'செக்அவுட் தளவமைப்பு','Design template' => 'வடிவமைப்பு டெம்ப்ளேட்','Dark mode' => 'இருண்ட பயன்முறை','Enable dark mode' => 'டார்க் பயன்முறையை இயக்கு','Logo image' => 'லோகோ படம்','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'செக்அவுட் பக்க தலைப்பில் காட்டப்பட வேண்டிய படத்தைத் தேர்வுசெய்யவும். கவனச்சிதறல் இல்லாத தலைப்பு மற்றும் அடிக்குறிப்பைப் பயன்படுத்தும் போது மட்டுமே இது பொருந்தும்.','Header background color' => 'தலைப்பு பின்னணி நிறம்','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'செக்அவுட் பக்க தலைப்புக்கு பின்னணி நிறத்தைத் தேர்வுசெய்யவும். கவனச்சிதறல் இல்லாத தலைப்பு மற்றும் அடிக்குறிப்பைப் பயன்படுத்தும் போது மட்டுமே இது பொருந்தும்.','HTML color value. ie: #f3f3f3' => 'HTML வண்ண மதிப்பு. அதாவது: #f3f3f3','Page background color' => 'பக்க பின்னணி நிறம்','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'செக்அவுட் பக்கத்திற்கான பின்னணி நிறத்தைத் தேர்வுசெய்யவும். <em>உள்ளடக்க</em> உறுப்புக்கு வண்ணம் பயன்படுத்தப்படுகிறது.','Footer background color' => 'அடிக்குறிப்பு பின்னணி நிறம்','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'செக்அவுட் பக்க அடிக்குறிப்புக்கு பின்னணி நிறத்தைத் தேர்வுசெய்யவும். கவனச்சிதறல் இல்லாத தலைப்பு மற்றும் அடிக்குறிப்பைப் பயன்படுத்தும் போது மட்டுமே இது பொருந்தும்.','Progress bar' => 'முன்னேற்றப் பட்டி','Make the checkout progress bar stay visible while scrolling' => 'உருட்டும்போது செக் அவுட் முன்னேற்றப் பட்டியை தெரியும்படி வைக்கவும்.','Express checkout' => 'எக்ஸ்பிரஸ் செக்அவுட்','Enable the express checkout section' => 'எக்ஸ்பிரஸ் செக்அவுட் பிரிவை இயக்கு.','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'ஆதரிக்கப்படும் கட்டண நுழைவாயில்கள் இந்த அம்சத்தை இயக்கியிருக்கும் போது, செக் அவுட்டில் எக்ஸ்பிரஸ் செக் அவுட் பிரிவைக் காண்பிக்கும்.','Display express checkout buttons in one line for larger screens' => 'பெரிய திரைகளுக்கு எக்ஸ்பிரஸ் செக்அவுட் பொத்தான்களை ஒரே வரியில் காட்டவும்.','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'இணக்கமான எக்ஸ்பிரஸ் செக்அவுட் கட்டண நுழைவாயில் மூலம் பணம் செலுத்தும்போது கூடுதல் செக்அவுட் தேவையான புலங்களை புறக்கணிக்கவும்.','Make the order summary stay visible while scrolling' => 'ஸ்க்ரோல் செய்யும்போது ஆர்டர் சுருக்கம் தெரியும்படி வைக்கவும்.','Choose a background color for the order summary section.' => 'ஆர்டர் சுருக்கப் பிரிவுக்கான பின்னணி வண்ணத்தைத் தேர்வுசெய்யவும்.','Highlight the order totals row in the order summary table' => 'ஆர்டர் சுருக்க அட்டவணையில் ஆர்டர் மொத்த வரிசையை முன்னிலைப்படுத்தவும்.','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'ஆர்டர் சுருக்கப் பிரிவில் ஹைலைட் செய்யப்பட்ட பின்னணி நிறம் இல்லாதபோது மிகவும் பயனுள்ளதாக இருக்கும். Fluid Checkout PRO ஐப் பயன்படுத்தும் போது, கார்ட், ஆர்டர் பெறப்பட்டது மற்றும் View ஆர்டர் பக்கங்களுக்கும் இது பொருந்தும்.','Action link on the order summary at checkout.' => 'செக் அவுட்டில் ஆர்டர் சுருக்கத்தில் செயல் இணைப்பு.','Edit cart link' => 'கூடை இணைப்பைத் திருத்து','Cart items count' => 'கூடை உருப்படிகளின் எண்ணிக்கை','Link to shop page' => 'கடைப் பக்கத்திற்கான இணைப்பு','Cart items' => 'கூடை பொருட்கள்','Hide cart items errors at the checkout page' => 'செக் அவுட் பக்கத்தில் கூடை உருப்படிகளின் பிழைகளை மறைக்கவும்.','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'செக்அவுட் பக்கத்தின் மேலே கூடை உருப்படிகளின் பிழைகள் செய்தியைக் காட்ட வேண்டாம். கொள்முதலை முடிக்க செக்அவுட் படிவத்தை சமர்ப்பிக்கும்போது, இந்த பிழை செய்திகள் எப்போதும் காட்டப்படும்.','Place order' => 'ஆர்டர் செய்','Define the position to display "Place order" and terms checkbox section.' => '&quot;வரிசைப்படுத்து&quot; மற்றும் சொற்கள் தேர்வுப்பெட்டிப் பகுதியைக் காண்பிக்க வேண்டிய நிலையை வரையறுக்கவும்.','Some options might not be compatible with some plugins and themes.' => 'சில விருப்பங்கள் சில செருகுநிரல்கள் மற்றும் கருப்பொருள்களுடன் இணக்கமாக இல்லாமல் இருக்கலாம்.','Below the payment section' => 'கட்டணப் பிரிவின் கீழே','Below the order summary' => 'ஆர்டர் சுருக்கம் கீழே','Both below the payment section and the order summary' => 'கட்டணப் பிரிவு மற்றும் ஆர்டர் சுருக்கம் இரண்டுக்கும் கீழே','Add widget areas to the checkout page' => 'செக்அவுட் பக்கத்தில் விட்ஜெட் பகுதிகளைச் சேர்க்கவும்.','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'இந்த விட்ஜெட் பகுதிகள், செக்அவுட் பக்கத்தில் நம்பிக்கை சின்னங்கள் மற்றும் நம்பிக்கை பேட்ஜ்களைச் சேர்க்கப் பயன்படுகின்றன.','Display the coupon codes section title' => 'கூப்பன் குறியீடுகள் பிரிவு தலைப்பைக் காண்பி.','Select position where to display the coupon codes section on the checkout page.' => 'செக்அவுட் பக்கத்தில் கூப்பன் குறியீடுகள் பகுதியை எங்கு காண்பிக்க வேண்டும் என்பதைத் தேர்ந்தெடுக்கவும்.','Before the checkout steps' => 'செக்அவுட் படிகளுக்கு முன்','As a substep before payment methods' => 'கட்டண முறைகளுக்கு முன் துணைப் படியாக','As a substep after payment methods' => 'கட்டண முறைகளுக்குப் பிறகு துணைப் படியாக','Default button style' => 'இயல்புநிலை பொத்தான் பாணி','"Add" link button' => '&quot;சேர்&quot; இணைப்பு பொத்தான்','Checkout fields' => 'செக்அவுட் புலங்கள்','Optional fields' => 'விருப்ப புலங்கள்','Hide optional fields behind a link button' => 'இணைப்பு பொத்தானுக்குப் பின்னால் விருப்ப புலங்களை மறை.','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'திறந்த உள்ளீட்டு புலங்களின் எண்ணிக்கையைக் குறைக்க இந்த விருப்பத்தைத் தேர்வுசெய்து வைத்திருப்பது பரிந்துரைக்கப்படுகிறது, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">ஆராய்ச்சியைப் படியுங்கள்</a> .','Do not hide "Address line 2" fields behind a link button' => 'இணைப்பு பொத்தானுக்குப் பின்னால் &quot;முகவரி வரி 2&quot; புலங்களை மறைக்க வேண்டாம்.','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'பெரும்பாலான வாடிக்கையாளர்களுக்கு &quot;முகவரி வரி 2&quot; புலம் உண்மையில் தேவைப்படும்போது அல்லது சரியான ஷிப்பிங் முகவரியைப் பெறுவது மிக முக்கியமானதாக இருக்கும்போது (அதாவது உணவு மற்றும் பிற அழுகக்கூடிய பொருட்களை டெலிவரி செய்தால்) மட்டுமே பரிந்துரைக்கப்படுகிறது.','Billing address' => 'பில்லிங் முகவரி','Select position where to display the billing address section on the checkout page.' => 'செக்அவுட் பக்கத்தில் பில்லிங் முகவரிப் பகுதியைக் காண்பிக்க வேண்டிய இடத்தைத் தேர்ந்தெடுக்கவும்.','As a step before shipping' => 'அனுப்புவதற்கு முன் ஒரு படியாக','As a sub-step before the shipping address section' => 'ஷிப்பிங் முகவரிப் பிரிவுக்கு முந்தைய துணைப் படியாக','As a sub-step after the shipping address section' => 'ஷிப்பிங் முகவரிப் பிரிவுக்குப் பிறகு துணைப் படியாக','As a step after shipping' => 'அனுப்பிய பிறகு ஒரு படியாக','As a sub-step before the payment section' => 'பணம் செலுத்தும் பிரிவுக்கு முந்தைய துணைப் படியாக','Force billing and shipping addresses to the same (single section)' => 'பில்லிங் மற்றும் ஷிப்பிங் முகவரிகளை ஒரே (ஒற்றைப் பிரிவு)க்கு கட்டாயப்படுத்தவும்.','Checkbox for "Same as shipping/billing address" checked by default' => '&quot;ஷிப்பிங்/பில்லிங் முகவரியைப் போன்றது&quot; என்பதற்கான தேர்வுப்பெட்டி இயல்பாகவே தேர்ந்தெடுக்கப்பட்டது.','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'ஷிப்பிங் முகவரிப் பிரிவு முதலில் காட்டப்படும்போது, &quot;ஷிப்பிங் முகவரியைப் போன்றது&quot; என்ற தேர்வுப்பெட்டி இயல்பாகவே தேர்வுசெய்யப்பட்டதாகத் தொடங்கும்.<br> பில்லிங் முகவரிப் பிரிவு முதலில் காட்டப்படும்போது, &quot;பில்லிங் முகவரியைப் போலவே&quot; என்ற தேர்வுப்பெட்டி முன்னிருப்பாகத் தேர்ந்தெடுக்கப்பட்டதாகத் தொடங்கும்.<br> செக் அவுட்டில் திறந்த உள்ளீட்டு புலங்களின் எண்ணிக்கையைக் கணிசமாகக் குறைக்க, இந்த விருப்பத்தைச் சரிபார்க்காமல் விடுவது பரிந்துரைக்கப்படுகிறது, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">ஆராய்ச்சியைப் படியுங்கள்</a> .','Highlight the billing address section in the checkout form' => 'செக்அவுட் படிவத்தில் பில்லிங் முகவரிப் பகுதியை முன்னிலைப்படுத்தவும்.','Shipping address' => 'அனுப்பும் முகவரி','Highlight the shipping address section in the checkout form' => 'செக்அவுட் படிவத்தில் ஷிப்பிங் முகவரிப் பகுதியை முன்னிலைப்படுத்தவும்.','Shipping methods' => 'அனுப்பும் முறைகள்','Choose in which position to display the shipping methods section.' => 'ஷிப்பிங் முறைகள் பகுதியை எந்த நிலையில் காண்பிக்க வேண்டும் என்பதைத் தேர்வுசெய்யவும்.','Before shipping address' => 'அனுப்புவதற்கு முந்தைய முகவரி','After shipping address' => 'அனுப்பிய பிறகு முகவரி','Local pickup' => 'உள்ளூர் பிக்அப் வசதி','Removes shipping address section when a local pickup shipping method is selected.' => 'உள்ளூர் பிக்அப் ஷிப்பிங் முறை தேர்ந்தெடுக்கப்படும்போது ஷிப்பிங் முகவரிப் பகுதியை நீக்குகிறது.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'உள்ளூர் பிக்அப் ஷிப்பிங் முறை தேர்ந்தெடுக்கப்படும்போது, ஷிப்பிங் முகவரியை பிக்அப் புள்ளி இருப்பிடத்துடன் மாற்றுகிறது.','Choose which address to save as the shipping address for local pickup orders.' => 'உள்ளூர் பிக்அப் ஆர்டர்களுக்கான ஷிப்பிங் முகவரியாக எந்த முகவரியைச் சேமிக்க வேண்டும் என்பதைத் தேர்வுசெய்யவும்.','Save the selected pickup location' => 'தேர்ந்தெடுக்கப்பட்ட பிக்அப் இடத்தைச் சேமிக்கவும்','Save same as the billing address' => 'பில்லிங் முகவரியைப் போலவே சேமிக்கவும்.','Do not save any shipping address' => 'எந்த ஷிப்பிங் முகவரியையும் சேமிக்க வேண்டாம்.','Company name field for shipping address' => 'ஷிப்பிங் முகவரிக்கான நிறுவனப் பெயர் புலம்','Change visibility for the company name field for the shipping address section on the checkout form.' => 'செக் அவுட் படிவத்தில் உள்ள ஷிப்பிங் முகவரிப் பகுதிக்கான நிறுவனத்தின் பெயர் புலத்திற்கான தெரிவுநிலையை மாற்றவும்.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'புலம் &quot;விருப்பத்தேர்வு&quot; என அமைக்கப்பட்டால், அது இயல்புநிலை தெரிவுநிலை நிலையாக இருந்தால், மற்ற செருகுநிரல்கள் தங்களுக்குத் தேவையான மாற்றங்களைப் பயன்படுத்த அனுமதிக்க எந்த மாற்றங்களும் பயன்படுத்தப்படாது.','Hidden (remove field)' => 'மறைக்கப்பட்டது (புலத்தை அகற்று)','Optional' => 'விருப்பத்தேர்வு','Required' => 'அவசியம்','Add shipping phone field to the checkout form.' => 'செக் அவுட் படிவத்தில் ஷிப்பிங் தொலைபேசி புலத்தைச் சேர்க்கவும்.','Choose in which step to display the shipping phone field.' => 'ஷிப்பிங் தொலைபேசி புலத்தை எந்தப் படியில் காட்ட வேண்டும் என்பதைத் தேர்வுசெய்யவும்.','Contact step' => 'தொடர்பு படி','Billing phone' => 'பில்லிங் தொலைபேசி','Add billing phone field to the checkout form.' => 'செக்அவுட் படிவத்தில் பில்லிங் தொலைபேசி புலத்தைச் சேர்க்கவும்.','Choose in which step to display the billing phone field.' => 'பில்லிங் தொலைபேசி புலத்தை எந்தப் படியில் காட்ட வேண்டும் என்பதைத் தேர்வுசெய்யவும்.','Show country code beside the flag' => 'கொடியின் அருகில் நாட்டின் குறியீட்டைக் காட்டு.','Show an example of a valid phone number inside phone fields' => 'தொலைபேசி புலங்களுக்குள் செல்லுபடியாகும் தொலைபேசி எண்ணின் உதாரணத்தைக் காட்டு.','Do not change placeholders' => 'ஒதுக்கிடங்களை மாற்ற வேண்டாம்.','Show if not defined' => 'வரையறுக்கப்படவில்லை என்றால் காட்டு','Always show' => 'எப்போதும் காட்டு','Order notes' => 'ஆர்டர் குறிப்புகள்','Define the visibility of the additional order notes field.' => 'கூடுதல் ஆர்டர் குறிப்புகள் புலத்தின் தெரிவுநிலையை வரையறுக்கவும்.','Gift options' => 'பரிசு விருப்பங்கள்','Allow customers to add a gift message and other gift related options to the order.' => 'வாடிக்கையாளர்கள் ஆர்டரில் பரிசு செய்தி மற்றும் பிற பரிசு தொடர்பான விருப்பங்களைச் சேர்க்க அனுமதிக்கவும்.','Display the gift message as part of the order details table instead of a separate section' => 'பரிசுச் செய்தியை தனிப் பிரிவிற்குப் பதிலாக ஆர்டர் விவரங்கள் அட்டவணையின் ஒரு பகுதியாகக் காட்டவும்.','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'இந்த விருப்பம் ஆர்டர் உறுதிப்படுத்தல் பக்கத்தையும் (நன்றி பக்கம்) கணக்குப் பக்கங்கள், மின்னஞ்சல்கள் மற்றும் பேக்கிங் சீட்டுகளில் உள்ள ஆர்டர் விவரங்களையும் பாதிக்கிறது.','Account matching' => 'கணக்கு பொருத்தம்','Enable the account matching feature' => 'கணக்கு பொருத்த அம்சத்தை இயக்கு.','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'வாடிக்கையாளரின் தொடர்பு விவரங்களுடன் ஒரு கணக்கு ஏற்கனவே இருக்கும்போது, விருந்தினர் வாடிக்கையாளரின் ஆர்டர்களை அவர்களின் தற்போதைய கணக்குடன் இணைக்கவும்.','Display message when an account exists with the email address provided' => 'வழங்கப்பட்ட மின்னஞ்சல் முகவரியுடன் ஒரு கணக்கு இருக்கும்போது செய்தியைக் காண்பி.','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'கணக்கு உருவாக்கப் புலங்களை அறிவிப்பு மற்றும் உள்நுழைவதற்கான விருப்பத்துடன் மாற்றுகிறது. சில சூழல்களில், வாடிக்கையாளர்களின் தனியுரிமையைப் பாதுகாக்க இந்த விருப்பத்தை முடக்க பரிந்துரைக்கப்படலாம்.','Dashboard' => 'டாஷ்போர்டு','Integrations' => 'ஒருங்கிணைப்புகள்','License keys' => 'உரிம விசைகள்','Visit our website for more information about our plugins and add-ons.' => 'எங்கள் செருகுநிரல்கள் மற்றும் துணை நிரல்கள் பற்றிய கூடுதல் தகவலுக்கு எங்கள் வலைத்தளத்தைப் பார்வையிடவும்.','Order pay page' => 'ஆர்டர் கட்டணப் பக்கம்','Order pay' => 'ஆர்டர் ஊதியம்','Enable order pay page optimizations' => 'ஆர்டர் கட்டணப் பக்க மேம்படுத்தல்களை இயக்கு','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'வாடிக்கையாளரிடமிருந்து பணம் செலுத்தப்பட வேண்டிய நிலுவையில் உள்ள ஏற்கனவே உள்ள ஆர்டர்களுக்கான ஆர்டர் கட்டணப் பக்கத்தின் அமைப்பை மாற்றுகிறது.','Add widget areas to the order pay page' => 'ஆர்டர் கட்டணப் பக்கத்தில் விட்ஜெட் பகுதிகளைச் சேர்க்கவும்.','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'இந்த விட்ஜெட் பகுதிகள் ஆர்டர் கட்டணப் பக்கத்தில் நம்பிக்கை சின்னங்கள் மற்றும் நம்பிக்கை பேட்ஜ்களைச் சேர்க்கப் பயன்படுகின்றன.','Thank you page & order details layout' => 'நன்றி பக்கம் &amp; ஆர்டர் விவரங்கள் தளவமைப்பு','Order details optimizations' => 'ஆர்டர் விவரங்கள் மேம்படுத்தல்கள்','Enable thank you page and order details optimizations' => 'நன்றி பக்கம் மற்றும் ஆர்டர் விவரங்கள் மேம்படுத்தல்களை இயக்கு.','Changes the layout of order details on the thank you page and account pages.' => 'நன்றி பக்கம் மற்றும் கணக்குப் பக்கங்களில் ஆர்டர் விவரங்களின் அமைப்பை மாற்றுகிறது.','Enable order details customizations on email notifications' => 'மின்னஞ்சல் அறிவிப்புகளில் ஆர்டர் விவரங்கள் தனிப்பயனாக்கங்களை இயக்கு.','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'மின்னஞ்சல் அறிவிப்புகளில் புதிய பிரிவுகளைக் காண்பிக்கவும், பிரிவுகளின் வரிசையை மாற்றவும். மின்னஞ்சல் அறிவிப்புகளில் உள்ள ஆர்டர் விவரங்களின் பாணிகள் மாறாமல் இருக்கும்.','Thank you page' => 'நன்றி பக்கம்','These options affect the thank you page, also known as order received or order confirmation pages.' => 'இந்த விருப்பங்கள் நன்றி பக்கத்தைப் பாதிக்கும், இது ஆர்டர் பெறப்பட்ட அல்லது ஆர்டர் உறுதிப்படுத்தல் பக்கங்கள் என்றும் அழைக்கப்படுகிறது.','Order details layout' => 'ஆர்டர் விவரங்களின் தளவமைப்பு','Display the order details with wide layout on the thank you page' => 'நன்றி பக்கத்தில் பரந்த தளவமைப்புடன் ஆர்டர் விவரங்களைக் காண்பி.','Add widget areas to the thank you page' => 'நன்றி பக்கத்தில் விட்ஜெட் பகுதிகளைச் சேர்க்கவும்.','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'இந்த விட்ஜெட் பகுதிகள் நன்றி பக்கத்தில் நம்பிக்கை சின்னங்கள் மற்றும் நம்பிக்கை பேட்ஜ்களைச் சேர்க்கப் பயன்படுகின்றன.','Order actions' => 'செயல்களை ஒழுங்குபடுத்து','Choose in which position to display the order actions.' => 'வரிசை செயல்களை எந்த நிலையில் காட்ட வேண்டும் என்பதைத் தேர்வுசெய்யவும்.','Inside the order overview' => 'ஆர்டர் கண்ணோட்டத்தின் உள்ளே','After the order overview' => 'ஆர்டர் மேலோட்டப் பார்வைக்குப் பிறகு','After order sections' => 'ஆர்டர் பிரிவுகளுக்குப் பிறகு','Order status' => 'ஆர்டர் நிலை','Display the order status progress bar' => 'ஆர்டர் நிலை முன்னேற்றப் பட்டியை காட்டு','Choose in which position to display the section.' => 'பகுதியை எந்த நிலையில் காண்பிக்க வேண்டும் என்பதைத் தேர்வுசெய்யவும்.','After the order overview and payment instructions' => 'ஆர்டர் கண்ணோட்டம் மற்றும் கட்டண வழிமுறைகளுக்குப் பிறகு','Before the order items section' => 'ஆர்டர் பொருட்கள் பிரிவுக்கு முன்','Inside the order items section' => 'ஆர்டர் பொருட்கள் பிரிவின் உள்ளே','After the order items section' => 'ஆர்டர் பொருட்கள் பிரிவுக்குப் பிறகு','On the sidebar' => 'பக்கப்பட்டியில்','Order downloads' => 'பதிவிறக்கங்களை ஆர்டர் செய்','Gift message' => 'பரிசுச் செய்தி','Tools' => 'கருவிகள்','Troubleshooting' => 'பழுது நீக்கும்','Debug options' => 'பிழைத்திருத்த விருப்பங்கள்','Debug mode' => 'பிழைத்திருத்த முறை','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'பிழைத்திருத்த பயன்முறையைப் பயன்படுத்துவது வலைத்தள செயல்திறனைப் பாதிக்கிறது. பிழைத்திருத்தத்தின் போது மட்டுமே இந்த விருப்பத்தைப் பயன்படுத்தவும்.','Load unminified assets' => 'குறைக்கப்படாத சொத்துக்களை ஏற்று','Enhanced select fields' => 'மேம்படுத்தப்பட்ட தேர்ந்தெடுக்கப்பட்ட புலங்கள்','Fix automatic zoom-in on form fields' => 'படிவ புலங்களில் தானியங்கி பெரிதாக்குதலை சரிசெய்யவும்.','Set <code>font-size</code> inside form fields to 16px' => 'படிவ புலங்களுக்குள் <code>font-size</code> 16px ஆக அமைக்கவும்.','Fluid Checkout' => 'திரவ செக்அவுட்','Settings' => 'அமைப்புகள்','Support' => 'ஆதரவு','(PRO)' => '(புரோ)','(experimental)' => '(சோதனை)','Please verify your phone number.' => 'உங்கள் தொலைபேசி எண்ணைச் சரிபார்க்கவும்.','The Bluehost Plugin' => 'ப்ளூஹோஸ்ட் செருகுநிரல்','Custom fields' => 'தனிப்பயன் புலங்கள்','Enable custom shipping email field' => 'தனிப்பயன் ஷிப்பிங் மின்னஞ்சல் புலத்தை இயக்கு','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'இயக்கப்பட்டால், Bluehost செருகுநிரலில் இருந்து ஷிப்பிங் மின்னஞ்சல் புலம் செக்அவுட் படிவத்தில் சேர்க்கப்படும்.','Captcha Pro by BestWebSoft' => 'BestWebSoft வழங்கும் கேப்ட்சா ப்ரோ','Captcha position' => 'கேப்ட்சா நிலை','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'கேப்ட்சா பிரிவைக் காண்பிக்க வேண்டிய நிலையை வரையறுக்கவும். தேர்ந்தெடுக்கப்பட்ட கேப்ட்சா வகையைப் பொறுத்து சில நிலைகள் வேலை செய்யாமல் போகலாம்.','Selecting a pickup point is required before proceeding.' => 'தொடர்வதற்கு முன் ஒரு பிக்அப் பாயிண்டைத் தேர்ந்தெடுப்பது அவசியம்.','Pickup point' => 'பிக்அப் பாயிண்ட்','Pickup point not selected yet.' => 'பிக்அப் பாயிண்ட் இன்னும் தேர்ந்தெடுக்கப்படவில்லை.','Pickup point:' => 'பிக்அப் பாயிண்ட்:','Mailchimp for WooCommerce' => 'WooCommerce க்கான Mailchimp','Subscribe checkbox' => 'குழுசேர் தேர்வுப்பெட்டி','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'செக்அவுட் பக்கத்தில் சந்தா தேர்வுப்பெட்டிக்கான நிலையை மீறி, அதை எப்போதும் தொடர்பு படியில் காட்டவும்.','Before Shipping Address' => 'அனுப்புவதற்கு முந்தைய முகவரி','(originally "%s")' => '(முதலில் &quot;%s&quot;)','After Shipping Address' => 'அனுப்பிய பிறகு முகவரி','Selecting a collection point is required when shipping with FermoPoint.' => 'FermoPoint உடன் அனுப்பும்போது ஒரு சேகரிப்பு புள்ளியைத் தேர்ந்தெடுப்பது அவசியம்.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'சரிபார்க்கப்பட்டால் பயனர்களுக்கு மின்னஞ்சலில் எழுத்துப்பிழைகள் தெரிவிக்கப்படும். (ஃப்ளூயிட் செக்அவுட் அம்சத்தை வழங்குவதால் இந்த அம்சம் முடக்கப்பட்டுள்ளது. இந்த விருப்பத்தில் மாற்றங்கள் நடைமுறைக்கு வராது)','Enable Mail Check: (disabled feature)' => 'அஞ்சல் சரிபார்ப்பை இயக்கு: (முடக்கப்பட்ட அம்சம்)','Carrier:' => 'கேரியர்:','Sendinblue - WooCommerce Email Marketing' => 'செண்டின்ப்ளூ - WooCommerce மின்னஞ்சல் மார்க்கெட்டிங்','Sign up checkbox position' => 'பதிவு செக்பாக்ஸ் நிலை','Move the sign up checkbox to the contact step' => 'பதிவு செக்பாக்ஸை தொடர்பு படிக்கு நகர்த்தவும்.','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'இயக்கப்படும்போது, Sendinblue செருகுநிரல் அமைப்புகளில் வரையறுக்கப்பட்ட காட்சி இருப்பிடத்தைப் பொருட்படுத்தாமல், தேர்வுப்பெட்டி தொடர்பு படிநிலைக்கு நகர்த்தப்படும்.','Theme Betheme' => 'தீம் பெத்தேம்','Checkout progress' => 'செக்அவுட் முன்னேற்றம்','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'செக்அவுட், வண்டி மற்றும் ஆர்டர் பெறப்பட்ட பக்கங்களில் பெத்தேமில் இருந்து செக்அவுட் படிகள் பகுதியை வெளியிடவும்.','Theme Fennik' => 'தீம் ஃபெனிக்','Breadcrumbs' => 'பிரட்தூள்களில் நனைக்கப்பட்டு','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Fluid Checkout தலைப்பு மற்றும் அடிக்குறிப்பைப் பயன்படுத்தும் போது Fennik தீமிலிருந்து பிரட்க்ரம்ப்ஸ் பகுதியை வெளியிடவும்.','Theme Go' => 'தீம் கோ','My account layout' => 'எனது கணக்கு அமைப்பு','Enable wide layout on "My account" page.' => '&quot;எனது கணக்கு&quot; பக்கத்தில் அகலமான அமைப்பை இயக்கு.','Theme Impreza' => 'தீம் இம்ப்ரெஸா','Header' => 'தலைப்பு','Spacing for site header at the checkout page (in pixels)' => 'செக்அவுட் பக்கத்தில் தள தலைப்புக்கான இடைவெளி (பிக்சல்களில்)','Only applicable when using the Impreza theme header at the checkout page.' => 'செக்அவுட் பக்கத்தில் இம்ப்ரெஸா தீம் தலைப்பைப் பயன்படுத்தும் போது மட்டுமே பொருந்தும்.','Theme Kapee' => 'தீம் கபீ','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'செக்அவுட், வண்டி மற்றும் ஆர்டர் பெறப்பட்ட பக்கங்களில் கேபி கருப்பொருளிலிருந்து செக்அவுட் படிகள் பகுதியை வெளியிடவும்.','Theme Porto' => 'தீம் போர்டோ','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'போர்டோ தீமில் இருந்து செக்அவுட் படிகள் பகுதியை செக்அவுட், வண்டி மற்றும் ஆர்டர் பெறப்பட்ட பக்கங்களில் வெளியிடவும்.','Theme Pressmart' => 'தீம் பிரஸ்மார்ட்','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'பிரஸ்மார்ட் கருப்பொருளிலிருந்து செக்அவுட் படிகள் பகுதியை செக்அவுட், வண்டி மற்றும் ஆர்டர் பெறப்பட்ட பக்கங்களில் வெளியிடவும்.','Theme The Gem' => 'தீம் தி ஜெம்','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Fluid Checkout தலைப்பு மற்றும் அடிக்குறிப்பைப் பயன்படுத்தும் போது The Gem தீமிலிருந்து Checkout படிகள் பகுதியை வெளியிடவும்.','Theme Woodmart' => 'தீம் வுட்மார்ட்','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Fluid Checkout தலைப்பு மற்றும் அடிக்குறிப்பைப் பயன்படுத்தும் போது Woodmart கருப்பொருளிலிருந்து checkout படிகள் பகுதியை வெளியிடவும்.','Checkout options' => 'வெளியேறுதல் விருப்பங்கள்','Disable the theme checkout options' => 'தீம் செக்அவுட் விருப்பங்களை முடக்கு.','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'தீம் மூலம் சேர்க்கப்பட்ட தயாரிப்பு படத்தைக் காண்பிக்கும் விருப்பங்கள், அளவு புலம், அகற்று பொத்தான் மற்றும் தயாரிப்பு பக்கத்திற்கான இணைப்பு ஆகியவை இயல்பாகவே முடக்கப்பட்டுள்ளன.','Theme Atomion' => 'தீம் ஆட்டமியன்','Order progress' => 'ஆர்டர் முன்னேற்றம்','Display order progress from the theme' => 'கருப்பொருளிலிருந்து ஆர்டர் முன்னேற்றத்தைக் காட்டு','Display the form field labels visible on the page' => 'பக்கத்தில் தெரியும் படிவ புல லேபிள்களைக் காண்பி.','It is recommended to keep this option enabled for a better user experience.' => 'சிறந்த பயனர் அனுபவத்திற்காக இந்த விருப்பத்தை இயக்கி வைத்திருப்பது பரிந்துரைக்கப்படுகிறது.','Theme ZK Nito' => 'தீம் ZK நிட்டோ','Add extra fields to the checkout form' => 'செக்அவுட் படிவத்தில் கூடுதல் புலங்களைச் சேர்க்கவும்.','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'ஷிப்பிங் முகவரிப் பிரிவில் கூடுதல் ஷிப்பிங் மின்னஞ்சல் மற்றும் ஷிப்பிங் தொலைபேசி புலத்தைச் சேர்க்கிறது.','Go to the home page' => 'முகப்புப் பக்கத்திற்குச் செல்லவும்.','Skip to content' => 'உள்ளடக்கத்திற்குச் செல்','Create an account' => 'ஒரு கணக்கை உருவாக்கு','Log in to your account' => 'உங்கள் கணக்கில் உள்நுழையவும்','Already have an account?' => 'ஏற்கனவே ஒரு கணக்கு உள்ளதா?','Logged in as %1$s. <a href="%2$s">Log out</a>' => '%1$s ஆக உள்நுழைந்துள்ளீர்கள். <a href="%2$s">வெளியேறு.</a>','Your order has a total amount due of %s. No further payment is needed.' => 'உங்கள் ஆர்டரில் மொத்த நிலுவைத் தொகை %s ஆகும். மேலும் கட்டணம் எதுவும் தேவையில்லை.','Close and continue with checkout' => 'மூடிவிட்டு செக் அவுட்டைத் தொடரவும்','Continue' => 'தொடரவும்','Parcel terminal' => 'பார்சல் முனையம்','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>இந்த விட்ஜெட், Fluid Checkout ஆல் மாற்றப்பட்டுள்ளது.</p><p> Fluid Checkout-ஐப் பயன்படுத்தும் போது, checkout பக்கம் சரியாக வேலை செய்ய அசல் WooCommerce சுருக்குக்குறியீட்டை <code>[woocommerce_checkout]</code> பயன்படுத்த வேண்டும்.</p><p> மேலும் தகவலுக்கு, திரவ செக்அவுட் ஆவணங்களைப் பார்வையிடவும்.</p>','Theme The7' => 'தீம் The7','Additional header sections' => 'கூடுதல் தலைப்புப் பிரிவுகள்','Output additional header sections if enabled in the theme settings.' => 'தீம் அமைப்புகளில் இயக்கப்பட்டிருந்தால் கூடுதல் தலைப்புப் பிரிவுகளை வெளியிடுங்கள்.','More information' => 'மேலும் தகவல்','Pick a Locker' => 'ஒரு லாக்கரைத் தேர்ந்தெடுக்கவும்','Page template' => 'பக்க டெம்ப்ளேட்','Use `Order confirmation` page template for block-based themes' => 'தொகுதி அடிப்படையிலான கருப்பொருள்களுக்கு `ஆர்டர் உறுதிப்படுத்தல்` பக்க டெம்ப்ளேட்டைப் பயன்படுத்தவும்.','Only applies when using a block-based theme.' => 'தொகுதி அடிப்படையிலான கருப்பொருளைப் பயன்படுத்தும் போது மட்டுமே பொருந்தும்.','WooCommerce Stripe Gateway' => 'WooCommerce ஸ்ட்ரைப் கேட்வே','Payment form' => 'பணம் செலுத்தும் படிவம்','Apply styles to the Stripe payment form fields' => 'ஸ்ட்ரைப் கட்டணப் படிவப் புலங்களுக்கு ஸ்டைல்களைப் பயன்படுத்துங்கள்','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'இயக்கப்பட்டிருக்கும் போது, செருகுநிரலுடன் இணக்கத்தன்மைக்கு உகந்ததாக வடிவமைக்கப்பட்ட பாணிகளை Fluid Checkout பயன்படுத்தும். நீங்கள் Stripe கட்டண படிவ புலங்களுக்கு தனிப்பயன் பாணிகளைப் பயன்படுத்துகிறீர்கள் என்றால் இதை முடக்க விரும்பலாம்.','Theme Nyture' => 'தீம் நைச்சர்','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Fluid Checkout ஐப் பயன்படுத்தும் போது Nyture கருப்பொருளிலிருந்து checkout படிகள் பகுதியை வெளியிடுங்கள்.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'கடை நிர்வாகியால் கைமுறையாக உருவாக்கப்பட்ட அல்லது செக் அவுட்டின் போது முடிக்கப்படாத ஆர்டர்களுக்கு வாடிக்கையாளர்கள் பணம் செலுத்த அனுமதிக்கிறது.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Quadlayers இன் WooCommerce Checkout Manager செருகுநிரல், Fluid Checkout உடன் இணக்கமாக இல்லை.','Company name field for billing address' => 'பில்லிங் முகவரிக்கான நிறுவனப் பெயர் புலம்','Change visibility for the company name field for the billing address section on the checkout form.' => 'செக்அவுட் படிவத்தில் பில்லிங் முகவரிப் பகுதிக்கான நிறுவனத்தின் பெயர் புலத்திற்கான தெரிவுநிலையை மாற்றவும்.','Theme Bookshelf' => 'தீம் புத்தக அலமாரி','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Fluid Checkout ஐப் பயன்படுத்தும் போது Bookshelf கருப்பொருளிலிருந்து Checkout படிகள் பகுதியை வெளியிடவும்.','Account password' => 'கணக்கு கடவுச்சொல்','An account will be created with the information provided at checkout when completing the order.' => 'ஆர்டரை முடிக்கும்போது செக் அவுட்டில் வழங்கப்படும் தகவலுடன் ஒரு கணக்கு உருவாக்கப்படும்.','Choose the style of the progress bar.' => 'முன்னேற்றப் பட்டியின் பாணியைத் தேர்வுசெய்யவும்.','Bars' => 'பார்கள்','Theme Ireca' => 'தீம் ஐரேகா','WooCommerce page layout' => 'WooCommerce பக்க அமைப்பு','Force wide layout on WooCommerce pages' => 'WooCommerce பக்கங்களில் பரந்த தளவமைப்பை கட்டாயப்படுத்துங்கள்.','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'இது WooCommerce பக்கங்களில் உள்ளடக்கப் பிரிவு மிகவும் குறுகலாக இல்லை என்பதை உறுதி செய்கிறது, இதில் செக்அவுட், வண்டி, ஆர்டர் பெறப்பட்டது, ஆர்டர் கட்டணம் மற்றும் கணக்குப் பக்கங்கள் ஆகியவை அடங்கும்.','WooCommerce Smart Coupons' => 'WooCommerce ஸ்மார்ட் கூப்பன்கள்','Position on checkout page' => 'செக்அவுட் பக்கத்தில் நிலை','Choose where to display the available coupons section on the checkout page.' => 'செக்அவுட் பக்கத்தில் கிடைக்கும் கூப்பன்கள் பகுதியை எங்கு காண்பிக்க வேண்டும் என்பதைத் தேர்வுசெய்யவும்.','Before the progress bar' => 'முன்னேற்றப் பட்டைக்கு முன்','After the progress bar' => 'முன்னேற்றப் பட்டிக்குப் பிறகு','Before coupon codes section' => 'கூப்பன் குறியீடுகளுக்கு முன் பிரிவு','Format phone numbers according to the rules for each country.' => 'ஒவ்வொரு நாட்டிற்கான விதிகளின்படி தொலைபேசி எண்களை வடிவமைக்கவும்.','Use precise phone number validation' => 'துல்லியமான தொலைபேசி எண் சரிபார்ப்பைப் பயன்படுத்தவும்','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'இது ஒரு சோதனை அம்சம், எல்லா அமைப்புகளிலும் எதிர்பார்த்தபடி வேலை செய்யாமல் போகலாம். இதை எச்சரிக்கையுடன் பயன்படுத்தவும்.','Phone number validation types used when precise validation is enabled.' => 'துல்லியமான சரிபார்ப்பு இயக்கப்பட்டிருக்கும் போது பயன்படுத்தப்படும் தொலைபேசி எண் சரிபார்ப்பு வகைகள்.','Mobile' => 'மொபைல்','Fixed line' => 'நிலையான வரி','Toll free' => 'கட்டணமில்லா சேவை','Or' => 'அல்லது','Contact' => 'தொடர்பு','Multi step' => 'பல படிகள்','2 columns' => '2 நெடுவரிசைகள்','1 column' => '1 நெடுவரிசை','Before checkout steps' => 'செக்அவுட்டுக்கு முன் படிகள்','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => '<em>&quot;1 நெடுவரிசை&quot;</em> செக்அவுட் அமைப்பைப் பயன்படுத்தும் போது இந்த விருப்பம் எப்போதும் <em>&quot;செக்அவுட் படிகளுக்கு முன்&quot;</em> என்று அமைக்கப்படும், மேலும் இது டெஸ்க்டாப் பார்வைக்கும் பொருந்தும்.','Position for the extra order summary section on mobile.' => 'மொபைலில் கூடுதல் ஆர்டர் சுருக்கப் பிரிவுக்கான நிலை.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => '<em>&quot;தளத் தலைப்பில்&quot;</em> என்ற விருப்பம் கவனச்சிதறல் இல்லாத தலைப்பைப் பயன்படுத்தும்போது மட்டுமே பொருந்தும்.','On the site header (requires distraction-free header)' => 'தளத் தலைப்பில் (கவனச்சிதறல் இல்லாத தலைப்பு தேவை)','Initial state for the expansible order summary section on mobile.' => 'மொபைலில் விரிவாக்கக்கூடிய ஆர்டர் சுருக்கப் பிரிவின் தொடக்க நிலை.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'ஒழுங்குமுறை தேவைகள் காரணமாக பின்வரும் நாடுகளுக்கு இதை <em>விரிவாக்கப்பட்டதாக</em> அமைக்க பரிந்துரைக்கிறோம்: <strong>ஜெர்மனி</strong> , <strong>ஆஸ்திரியா</strong> , <strong>சுவிட்சர்லாந்து</strong> , <strong>நெதர்லாந்து</strong> , <strong>போலந்து</strong> , <strong>பெல்ஜியம்</strong> மற்றும் <strong>பிரான்ஸ்</strong> .','Collapsed' => 'சுருக்கப்பட்டது','Expanded' => 'விரிவாக்கப்பட்டது','Do not show' => 'காட்டாதே','yes' => 'ஆம்','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'ஷிப்பிங் முகவரிப் பகுதிக்குப் பிறகு பில்லிங் முகவரிப் பகுதி காட்டப்பட்டு, பில்லிங் தொலைபேசி எண் புலம் &#39;தேவை&#39; என அமைக்கப்பட்டிருந்தால், அந்தப் புலம் &#39;தேவை&#39; எனக் கட்டாயப்படுத்தப்படலாம். அந்த விருப்பம் சரிபார்க்கப்படும்போது, ஷிப்பிங் முகவரியை பில்லிங் முகவரிக்கு நகலெடுக்க முடியும் என்பதை உறுதிப்படுத்த இது அவசியமாகும்; இல்லையெனில், வாடிக்கையாளரால் செக்அவுட் படிவத்தைப் பூர்த்தி செய்ய முடியாமல் போகலாம்.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'ஷிப்பிங் முகவரிப் பகுதிக்கு முன் பில்லிங் முகவரிப் பகுதி காட்டப்பட்டு, ஷிப்பிங் தொலைபேசி எண் &#39;தேவை&#39; என அமைக்கப்பட்டிருந்தால், பில்லிங் தொலைபேசி எண் புலம் &#39;தேவை&#39; எனக் கட்டாயப்படுத்தப்படலாம். அந்த விருப்பம் சரிபார்க்கப்படும்போது, ஷிப்பிங் முகவரியை பில்லிங் முகவரிக்கு நகலெடுக்க முடியும் என்பதை உறுதிப்படுத்த இது தேவைப்படுகிறது; இல்லையெனில், வாடிக்கையாளரால் செக்அவுட் படிவத்தைப் பூர்த்தி செய்ய முடியாமல் போகலாம்.','Settings profiles' => 'அமைப்புகள் சுயவிவரங்கள்','Settings profile' => 'அமைப்புகள் சுயவிவரம்','You do not have permission to perform this action.' => 'இந்தச் செயலைச் செய்வதற்கு உங்களுக்கு அனுமதி இல்லை.','You do not have permission to activate plugins.' => 'செருகுநிரல்களைச் செயல்படுத்த உங்களுக்கு அனுமதி இல்லை.','Missing plugin.' => 'செருகுநிரல் காணவில்லை.','Plugin activated.' => 'செருகுநிரல் செயல்படுத்தல்.','The following changes will be applied:' => 'பின்வரும் மாற்றங்கள் செயல்படுத்தப்படும்:','Delete leftover options' => 'மீதமுள்ள விருப்பங்களை நீக்கவும்','This preview has expired. Reload the admin page to start a new preview.' => 'இந்த முன்னோட்டம் காலாவதியாகிவிட்டது. புதிய முன்னோட்டத்தைத் தொடங்க, நிர்வாகப் பக்கத்தை மீண்டும் ஏற்றவும்.','Preview expired' => 'முன்னோட்டம் காலாவதியானது','Orders cannot be placed in the preview.' => 'முன்னோட்டத்தில் ஆர்டர்களை இட முடியாது.','Logging in is not available in the preview.' => 'முன்னோட்டத்தில் உள்நுழைதல் வசதி இல்லை.','Accounts cannot be created in the preview.' => 'முன்னோட்டத்தில் கணக்குகளை உருவாக்க முடியாது.','Requests to other sites are blocked in the preview.' => 'முன்னோட்டத்தில் மற்ற தளங்களுக்கான கோரிக்கைகள் தடுக்கப்பட்டுள்ளன.','Processing…' => 'செயலாக்கம்…','Something went wrong. Please try again.' => 'ஏதோ தவறு நிகழ்ந்துவிட்டது. தயவுசெய்து மீண்டும் முயற்சிக்கவும்.','Activate plugin' => 'செருகுநிரலைச் செயல்படுத்து','Fluid Checkout PRO - The complete checkout package' => 'ஃப்ளூயிட் செக்அவுட் ப்ரோ - முழுமையான செக்அவுட் தொகுப்பு','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'அனைத்து PRO அம்சங்களும் + அனைத்து கூடுதல் சேவைகளும், ஒரே விலையில். வடிவமைப்பு டெம்ப்ளேட்கள், மேம்படுத்தப்பட்ட கார்ட் மற்றும் ஆர்டர் பெறப்பட்ட பக்கங்கள், கணக்கு பொருத்தம் மற்றும் இன்னும் பல.','Optimized order pay page' => 'மேம்படுத்தப்பட்ட ஆர்டர் கட்டணப் பக்கம்','Delayed account creation' => 'கணக்கு உருவாக்கம் தாமதமானது','Address autocomplete with Google Maps APIs' => 'கூகிள் மேப்ஸ் ஏபிஐ-கள் மூலம் முகவரியைத் தானாக நிரப்புதல்','Multiple saved addresses with the address book' => 'முகவரிப் புத்தகத்தில் பல முகவரிகள் சேமிக்கப்பட்டுள்ளன.','EU-VAT assistant' => 'ஐரோப்பிய ஒன்றிய மதிப்புக்கூட்டு வரி உதவியாளர்','Hide this section' => 'இந்தப் பகுதியை மறைக்கவும்','Learn more' => 'மேலும் அறிக','Get early access' => 'முன்கூட்டிய அணுகலைப் பெறுங்கள்','Activate add-on' => 'துணை நிரலைச் செயல்படுத்து','Get more out of your checkout journey' => 'உங்கள் பணம் செலுத்தும் அனுபவத்திலிருந்து அதிகப் பலன்களைப் பெறுங்கள்.','Test API key' => 'சோதனை API விசை','Guided setup' => 'வழிகாட்டப்பட்ட அமைப்பு','Options' => 'விருப்பங்கள்','Set up layout and design on the <a href="%s">checkout options</a>.' => '<a href="%s">செக்அவுட் விருப்பங்களில்</a> தளவமைப்பு மற்றும் வடிவமைப்பை அமைக்கவும்.','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'விருந்தினர் செக்-அவுட்டை இயக்கவும் மற்றும்/அல்லது <a href="%s">வாடிக்கையாளர் கணக்கு அமைப்புகளை</a> மதிப்பாய்வு செய்யவும்.','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'மேம்படுத்தப்பட்ட <a href="%1$s">வண்டி</a> , <a href="%2$s">நன்றி</a> மற்றும் <a href="%3$s">ஆர்டர் கட்டணப்</a> பக்கங்களைச் செயல்படுத்துங்கள்.','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'கூகுள் மேப்ஸில் <a href="%s">முகவரி தானாக நிரப்புதலைச்</a> செயல்படுத்துங்கள்.','Enable multiple saved addresses with <a href="%s">address book</a>.' => '<a href="%s">முகவரிப் புத்தகத்தில்</a> பல சேமிக்கப்பட்ட முகவரிகளைச் செயல்படுத்துங்கள்.','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'நீங்கள் நிறுவியுள்ள தீம் அல்லது பிற செருகுநிரல்களுக்கு ஏதேனும் <a href="%s">ஒருங்கிணைப்பு விருப்பங்கள்</a> உள்ளனவா எனச் சரிபார்க்கவும்.','Missing settings tab.' => 'அமைப்புகள் பகுதி காணவில்லை.','Getting started' => 'தொடங்குதல்','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>அற்புதம்! உங்கள் செக்அவுட் பக்கம் இப்போது Fluid Checkout-இல் இயங்குகிறது.</strong> தொடங்குவதற்கான சில வழிமுறைகள் இதோ:','Completed' => 'நிறைவுற்றது','Send now' => 'இப்போது அனுப்பு','Auto-detect' => 'தானாகக் கண்டறியும்','Afrikaans' => 'ஆஃப்ரிகான்ஸ்','Albanian' => 'அல்பேனியன்','Amharic' => 'அம்ஹாரிக்','Arabic' => 'அரபு','Armenian' => 'ஆர்மேனியன்','Azerbaijani' => 'அசர்பைஜானி','Basque' => 'பாஸ்க்','Belarusian' => 'பெலாரஷ்யன்','Bengali' => 'பெங்காலி','Bosnian' => 'போஸ்னியன்','Bulgarian' => 'பல்கேரியன்','Burmese' => 'பர்மிய','Catalan' => 'கட்டலான்','Chinese' => 'சீன','Chinese (Simplified)' => 'சீனம் (எளிதாக்கப்பட்டது)','Chinese (Hong Kong)' => 'சீன (ஹாங்காங்)','Chinese (Traditional)' => 'சீன (பாரம்பரிய)','Croatian' => 'குரோஷியன்','Czech' => 'செக்','Danish' => 'டேனிஷ்','Dutch' => 'டச்சு','English' => 'ஆங்கிலம்','English (Australian)' => 'ஆங்கிலம் (ஆஸ்திரேலிய)','English (Great Britain)' => 'ஆங்கிலம் (கிரேட் பிரிட்டன்)','Estonian' => 'எஸ்டோனியன்','Farsi' => 'பாரசீகம்','Finnish' => 'ஃபின்னிஷ்','Filipino' => 'பிலிப்பினோ','French' => 'பிரெஞ்சு','French (Canadian)' => 'பிரெஞ்சு (கனடிய)','Galician' => 'காலிசியன்','Georgian' => 'ஜார்ஜிய','German' => 'ஜெர்மன்','Greek' => 'கிரேக்கம்','Gujarati' => 'குஜராத்தி','Hebrew' => 'ஹீப்ரு','Hindi' => 'ஹிந்தி','Hungarian' => 'ஹங்கேரியன்','Icelandic' => 'ஐஸ்லாந்திய','Indonesian' => 'இந்தோனேசிய','Italian' => 'இத்தாலிய','Japanese' => 'ஜப்பானிய','Kannada' => 'கன்னடம்','Kazakh' => 'கசாக்','Khmer' => 'கெமர்','Korean' => 'கொரியன்','Kyrgyz' => 'கிர்கிஸ்','Lao' => 'லாவோ','Latvian' => 'லாட்வியன்','Lithuanian' => 'லிதுவேனியன்','Macedonian' => 'மாசிடோனியன்','Malay' => 'மலாய்','Malayalam' => 'மலையாளம்','Marathi' => 'மராத்தி','Mongolian' => 'மங்கோலியன்','Nepali' => 'நேபாளி','Norwegian' => 'நார்வேஜியன்','Polish' => 'போலிஷ்','Portuguese' => 'போர்த்துகீசியம்','Portuguese (Brazil)' => 'போர்த்துகீசியம் (பிரேசில்)','Portuguese (Portugal)' => 'போர்த்துகீசியம் (போர்ச்சுகல்)','Punjabi' => 'பஞ்சாபி','Romanian' => 'ரோமானியன்','Russian' => 'ரஷ்யன்','Serbian' => 'செர்பியன்','Sinhalese' => 'சிங்களம்','Slovak' => 'ஸ்லோவாக்','Slovenian' => 'ஸ்லோவேனியன்','Spanish' => 'ஸ்பானிஷ்','Spanish (Latin America)' => 'ஸ்பானிஷ் (லத்தீன் அமெரிக்கா)','Swahili' => 'சுவாஹிலி','Swedish' => 'ஸ்வீடிஷ்','Tamil' => 'நாகர்','Telugu' => 'தெலுங்கு','Thai' => 'தாய்','Turkish' => 'துருக்கியம்','Ukrainian' => 'உக்ரேனிய','Urdu' => 'உருது','Vietnamese' => 'வியட்நாமிய','Zulu' => 'ஜூலு','Google address autocomplete' => 'கூகிள் முகவரி தானியங்கு நிரப்புதல்','Google Places API version' => 'கூகிள் பிளேசஸ் ஏபிஐ பதிப்பு','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'கூகுள் பிளேசஸ் ஏபிஐ-யின் எந்தப் பதிப்பைப் பயன்படுத்த வேண்டும் என்பதைத் தேர்வுசெய்யுங்கள். கூடிய விரைவில் புதிய பிளேசஸ் ஏபிஐ-க்கு மாறுமாறு நாங்கள் பரிந்துரைக்கிறோம்.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'மார்ச் 1, 2025 முதல், கூகிள் &quot;Places API (Legacy)&quot; பதிப்பை மரபு நிலைக்கு (Legacy status) மாற்றும் என்பதால், &quot;Places API (New)&quot;-ஐப் பயன்படுத்துமாறு நாங்கள் பரிந்துரைக்கிறோம். இதன் பொருள், புதிய API திறவிகளுக்கு (API keys) இந்தச் சேவையை உங்களால் இனி இயக்க முடியாது என்பதும், அந்த API பதிப்பு காலப்போக்கில் இனி கிடைக்காது என்பதுமாகும். ஏற்கனவே மரபு API-ஐப் பயன்படுத்தும் கணக்குகள் எந்த இடையூறும் இன்றி தொடர்ந்து செயல்படலாம்.','(Recommended)' => '(பரிந்துரைக்கப்படுகிறது)','Google API key' => 'கூகிள் ஏபிஐ சாவி','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'உங்கள் கூகுள் ஏபிஐ கீயை ஒட்டி, அது இந்த இணையதளத்தில் செயல்படுகிறதா என்பதை உறுதிப்படுத்த சோதனைப் பொத்தானைப் பயன்படுத்தவும். அந்த கீ செல்லுபடியாகும் மற்றும் உங்கள் டொமைனுக்கு அனுமதிக்கப்பட்டதா என்பதை உறுதிப்படுத்திக் கொள்ளுங்கள், இல்லையெனில் முகவரிப் புலம் தடுக்கப்பட்டு, வாடிக்கையாளர்கள் தங்கள் ஆர்டர்களை முடிக்க முடியாமல் போகலாம்.','Enable Google address autocomplete' => 'கூகிள் முகவரி தானியங்கு நிரப்பலை இயக்கு','Enable address autocompletion using the Google Maps APIs.' => 'கூகுள் மேப்ஸ் ஏபிஐ-களைப் பயன்படுத்தி முகவரி தானியங்கு நிறைவை இயக்குங்கள்.','Google API language' => 'கூகிள் ஏபிஐ மொழி','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'கூகுள் பிளேசஸ் ஏபிஐ முகவரிப் பரிந்துரைகளைக் காண்பிக்க இந்த மொழி பயன்படுத்தப்படும், மேலும் முகவரிகள் இந்த மொழியில் தானாகவே பூர்த்தி செய்யப்படும்.','Result types' => 'முடிவு வகைகள்','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'எந்த வகையான முடிவுகளையும் ஏற்க இதை காலியாக விடவும்; இது பொதுவாக சிறந்த பொருத்த முடிவுகளைத் தரும். <a href="%s" target="_blank">மேலும் விவரங்களுக்கு ஆவணங்களைப் பார்க்கவும்</a> .<br> முகவரி தானியங்கு நிரப்பு புலங்களில் காண்பிக்க, 5 வகையான முகவரி தேடல் முடிவுகள் வரை தேர்ந்தெடுக்கவும்.<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">ஆதரிக்கப்படும் வகைகள்</a> பற்றி மேலும் அறிந்துகொள்ள, கூகுள் மேப்ஸ் ஆவணங்களைப் பார்வையிடவும்.','Result types (Legacy API)' => 'முடிவு வகைகள் (பழைய ஏபிஐ)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Places API (பழைய பதிப்பு) ஐப் பயன்படுத்தும்போது எந்த வகையான முகவரித் தேடல் முடிவுகளைத் திரும்பப் பெற வேண்டும்.<br> <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">ஆதரிக்கப்படும் வகைகளைப்</a> பற்றி மேலும் அறிந்துகொள்ள, மரபுவழி கூகுள் பிளேசஸ் ஏபிஐ-யின் ஆவணங்களைப் பார்வையிடவும்.','Company fields' => 'நிறுவனத் துறைகள்','Enable autocomplete for the company name if available' => 'நிறுவனத்தின் பெயரைத் தானாக நிரப்பும் வசதி இருந்தால், அதைச் செயல்படுத்தவும்.','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'கூகுள் மேப்ஸ் ஏபிஐ-களிலிருந்து நிறுவனத்தின் பெயர் தகவல் திரும்பப் பெறப்படும்போது, நிறுவனப் புலம் தானாகவே நிரப்பப்படுவதை இயக்கவும்.','Business search' => 'வணிகத் தேடல்','Enable search for businesses in the company field' => 'நிறுவனப் புலத்தில் வணிகங்களைத் தேடுவதை இயக்கு','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'நிறுவனப் புலத்தில் தட்டச்சு செய்யும்போது, ஒரு வணிகத்துடன் தொடர்புடைய முகவரிகளின் பரிந்துரையை இயக்கவும்; பின்னர், பரிந்துரைகளிலிருந்து ஒரு வணிகம் தேர்ந்தெடுக்கப்படும்போது, அனைத்து முகவரிப் புலங்களையும் தானாகவே நிரப்பவும்.','Company result types' => 'நிறுவன முடிவு வகைகள்','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'தானாக நிரப்பும் நிறுவனப் புலங்களில் காண்பிக்க, 5 வகையான முகவரித் தேடல் முடிவுகள் வரை தேர்ந்தெடுக்கவும்.<br> பரிந்துரைக்கப்பட்ட மதிப்பு என்பது <code>establishment</code> ஆகும், இதில் பெரும்பாலான வணிக வகைகள் அடங்கும்.<br> வணிகங்கள் தொடர்பில்லாத முடிவுகள் உட்பட, எந்த வகையான முடிவுகளையும் ஏற்க, இதை காலியாக விடவும்.<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">ஆதரிக்கப்படும் வகைகள்</a> பற்றி மேலும் அறிந்துகொள்ள, கூகுள் மேப்ஸ் ஆவணங்களைப் பார்வையிடவும்.','Google logo' => 'கூகிள் லோகோ','Show text and logo "Powered by Google"' => '&quot;கூகிளால் இயக்கப்படுகிறது&quot; என்ற உரையையும் சின்னத்தையும் காட்டு','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'தேர்வுசெய்யப்பட்டால், முகவரித் தானியங்குப் பரிந்துரைப் பெட்டியின் கீழே &quot;Powered by Google&quot; என்ற உரையும் இலச்சினையும் காட்டப்படும்.','Brasil API address autocomplete' => 'பிரேசில் API முகவரி தானியங்கு நிரப்புதல்','Brasil API' => 'பிரேசில் ஏபிஐ','Enable Brasil API address autocomplete for CEP fields' => 'CEP புலங்களுக்கான பிரேசில் API முகவரி தானியங்கு நிரப்புதலைச் செயல்படுத்தவும்','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'CEP/அஞ்சல் குறியீடு புலத்தைப் பயன்படுத்தி முகவரிகளை மீட்டெடுத்துத் தானாக நிரப்ப பிரேசில் API-ஐப் பயன்படுத்தவும். இது பிரேசிலிய முகவரிகளுக்கு மட்டுமே பொருந்தும்.','API version' => 'ஏபிஐ பதிப்பு','Choose which version of the Brasil API CEP method to use.' => 'பிரேசில் API CEP முறையின் எந்தப் பதிப்பைப் பயன்படுத்த வேண்டும் என்பதைத் தேர்வுசெய்யவும்.','Address book migration' => 'முகவரிப் புத்தக இடமாற்றம்','WooCommerce addresses' => 'WooCommerce முகவரிகள்','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'WooCommerce-இல் ஏற்கனவே உள்ள ஷிப்பிங் மற்றும் பில்லிங் முகவரிகளை வாடிக்கையாளர்களின் முகவரிப் புத்தகத்தில் நகலெடுக்கவும்.','Enable the address book feature' => 'முகவரிப் புத்தக அம்சத்தை இயக்கு','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'வாடிக்கையாளர்கள் பல முகவரிகளைச் சேமிக்கவும், அனுப்புதல் மற்றும் கட்டணப் பட்டியலுக்காகப் பயன்படுத்தப்பட வேண்டிய இயல்புநிலை முகவரியை வரையறுக்கவும் அனுமதிக்கவும்.','Address labels' => 'முகவரி லேபிள்கள்','Allow customers to add a custom label for each address' => 'ஒவ்வொரு முகவரிக்கும் வாடிக்கையாளர்கள் ஒரு தனிப்பயன் லேபிளைச் சேர்க்க அனுமதிக்கவும்.','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'முகவரி லேபிள்கள், வாடிக்கையாளர்கள் தாங்கள் சேமித்த முகவரிகளை (உதாரணமாக: &quot;அம்மாவின் வீடு&quot;) எளிதாக வேறுபடுத்தி அறிய உதவுகின்றன. இந்த முகவரி லேபிள்கள் வாடிக்கையாளர்களுக்கு மட்டுமேயானவை, மேலும் அவை ஆர்டர் விவரங்கள் பக்கத்திலோ அல்லது விலைப்பட்டியல்களிலோ காட்டப்படவோ அச்சிடப்படவோ மாட்டாது.','Display layout' => 'காட்சி தளவமைப்பு','Choose how saved addresses are displayed at checkout and on the cart.' => 'பணம் செலுத்தும்போதும், வண்டியிலும் சேமிக்கப்பட்ட முகவரிகள் எவ்வாறு காட்டப்பட வேண்டும் என்பதைத் தேர்வுசெய்யவும்.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'பணம் செலுத்தும்போதும் மற்றும் கார்ட்டிலும் இது பொருந்தும். கணக்குப் பக்கத்தில் சேமிக்கப்பட்ட முகவரிகள் எப்போதும் கார்டுகளின் தளவமைப்பையே பயன்படுத்தும்.','Address cards' => 'முகவரி அட்டைகள்','Address list' => 'முகவரி பட்டியல்','Dropdown field' => 'கீழ்விரி புலம்','Address search' => 'முகவரிகள் தேடல்','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'வாடிக்கையாளரிடம் குறைந்தபட்சம் இந்த எண்ணிக்கையிலான சேமிக்கப்பட்ட முகவரிகள் இருக்கும்போது, முன்பக்கத்தில் முகவரித் தேடல் வடிப்பானைக் காண்பிக்கவும்.','Not used when display layout is set to dropdown field.' => 'காட்சி தளவமைப்பு கீழ்தோன்றும் புலமாக அமைக்கப்பட்டிருக்கும்போது பயன்படுத்தப்படாது.','Addresses' => 'முகவரிகள்','Enable cart page optimizations to see more options' => 'கூடுதல் விருப்பங்களைக் காண, கார்ட் பக்க மேம்படுத்தல்களைச் செயல்படுத்தவும்.','Sticky order summary' => 'ஸ்டிக்கி ஆர்டர் சுருக்கம்','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'கார்ட் பக்கத்தில் கூப்பன் குறியீடுகள் பகுதியைக் காண்பிக்க வேண்டிய இடத்தைத் தேர்ந்தெடுக்கவும். AJAX கார்ட் இயக்கப்பட்டிருக்கும்போதும், WooCommerce அமைப்புகளில் கூப்பன் குறியீடுகளின் பயன்பாடு இயக்கப்பட்டிருக்கும்போதும் மட்டுமே இது பொருந்தும்.','Layout of cross-sell' => 'குறுக்கு விற்பனையின் தளவமைப்பு','Cross-sells displayed' => 'குறுக்கு விற்பனைகள் காட்டப்பட்டன','Items' => 'பொருட்கள்','Cart page optimization' => 'கார்ட் பக்க மேம்படுத்தல்','Give your cart the same clear, conversion-focused layout as your checkout.' => 'உங்கள் செக்அவுட்டைப் போலவே, உங்கள் கார்ட்டுக்குமான தெளிவான, விற்பனையை அதிகரிக்கும் வடிவமைப்பை அமையுங்கள்.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'சீரான கொள்முதல் அனுபவத்தைப் பெற, கார்ட் அமைப்பை செக்அவுட் பக்கத்துடன் பொருத்துங்கள்.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'கார்ட்டை எப்போதும் பின்னணியில் புதுப்பித்த நிலையில் வைத்திருங்கள், பொருட்களின் அளவு மாறும்போது முழுப் பக்கமும் மீண்டும் ஏற்றப்படாது.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'கூப்பன் குறியீடுகள், ஷிப்பிங் மற்றும் கிராஸ்-செல்களை, அவை சிறந்த பலனைத் தரும் இடங்களில் துல்லியமாக வைக்கவும்.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'ஸ்க்ரோல் செய்யும்போதும் ஆர்டர் சுருக்கம் தெரியும்படி வைக்கவும், மேலும் வாடிக்கையாளர்களுக்கு உறுதி தேவைப்படும் இடங்களில் நம்பிக்கைச் சின்னங்களைச் சேர்க்கவும்.','Columns' => 'நெடுவரிசைகள்','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => '<em>&quot;Split&quot;</em> வடிவமைப்பு வார்ப்புருவுடன் <em>&quot;1 column&quot;</em> தளவமைப்பைப் பயன்படுத்தும்போது, பக்கத்தின் பக்கவாட்டுப் பட்டி விட்ஜெட் பகுதி (செக்அவுட் பக்கவாட்டுப் பட்டி, கார்ட் பக்கவாட்டுப் பட்டி அல்லது ஆர்டர் பெறப்பட்ட பக்கவாட்டுப் பட்டி) செயலில் இருந்தால் மட்டுமே ஒரு வலது நெடுவரிசை காட்டப்படும். இல்லையெனில், பக்கம் Split பாணிகளுடன் ஒற்றை நெடுவரிசையாகவே இருக்கும்.','Split column background' => 'பிளவுபட்ட நெடுவரிசை பின்னணி','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'ஸ்பிளிட் டிசைன் இரண்டாம் நிலை நெடுவரிசைக்கு ஒரு பின்னணி நிறத்தைத் தேர்ந்தெடுக்கவும். ஆர்டர் சுருக்கத்தின் பின்னணி நிறத்தைப் பயன்படுத்த, இதை காலியாக விடவும்.','Page templates' => 'பக்க வார்ப்புருக்கள்','Checkout template' => 'செக்அவுட் டெம்ப்ளேட்','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'பணம் செலுத்தும் இடத்தில் கவனச்சிதறல்களைக் குறைக்க இது பரிந்துரைக்கப்படுகிறது. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">கார்ட் கைவிடுதல் பற்றிய ஆய்வைப் படியுங்கள்</a> .','Sticky progress bar' => 'ஒட்டும் முன்னேற்றப் பட்டை','Progress bar style' => 'முன்னேற்றப் பட்டி பாணி','Order totals' => 'ஆர்டர் மொத்தங்கள்','Background color' => 'பின்னணி நிறம்','Action link' => 'செயல் இணைப்பு','Mobile order summary' => 'மொபைல் ஆர்டர் சுருக்கம்','Mobile initial state' => 'மொபைல் ஆரம்ப நிலை','Enable editing cart items at checkout' => 'பணம் செலுத்தும் இடத்தில் வண்டியில் உள்ள பொருட்களைத் திருத்துவதை இயக்கு','Allow customers to change product quantities or remove items directly at the checkout page.' => 'வாடிக்கையாளர்கள் செக்அவுட் பக்கத்திலேயே பொருட்களின் அளவுகளை மாற்றவோ அல்லது பொருட்களை நீக்கவோ அனுமதிக்கவும்.','Cart item errors' => 'வண்டிப் பொருள் பிழைகள்','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'செக்அவுட் அல்லது கார்ட் பக்கங்களில் கூப்பன் குறியீடு ஒரு தனிப் பிரிவாகக் காட்டப்படும்போதும், WooCommerce அமைப்புகளில் கூப்பன் குறியீடுகளின் பயன்பாடு இயக்கப்பட்டிருக்கும்போதும் மட்டுமே இது பொருந்தும்.','Coupon codes position' => 'கூப்பன் குறியீடுகளின் நிலை','Apply coupon button' => 'கூப்பனைப் பயன்படுத்து பொத்தான்','Select style of the "apply coupon" button.' => '&quot;கூப்பனைப் பயன்படுத்து&quot; பொத்தானின் பாணியைத் தேர்ந்தெடுக்கவும்.','Address line 2' => 'முகவரி வரி 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'இந்த அமைப்பு, செக்அவுட் மற்றும் உள்ளூர் பிக்கப் ஆகிய பிரிவுகளுக்கு இடையில் பகிரப்படுகிறது. உள்ளூர் பிக்கப் பிரிவில், ஷிப்/பிக்கப் தேர்வியானது, ஷிப்பிங் முறைப் பிரிவின் உள்ளே (முகவரிக்கு முன்) காட்டப்பட வேண்டுமா அல்லது ஒரு தனிப் பிரிவாக (பின்) காட்டப்பட வேண்டுமா என்பதையும் இது தீர்மானிக்கிறது.','Customer accounts' => 'வாடிக்கையாளர் கணக்குகள்','Guest checkout' => 'விருந்தினர் சரிபார்க்கப்பட்டார்','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'WooCommerce கணக்குகள் அமைப்புகள் பக்கத்தில் உள்ள விருந்தினர் செக்அவுட், உள்நுழைவு மற்றும் கணக்கு உருவாக்கும் விருப்பங்கள். உங்கள் வசதிக்காக அவை இங்கே நிர்வகிக்கப்படுகின்றன, எனவே ஒவ்வொரு அமைப்புகள் சுயவிவரத்திற்கும் நீங்கள் வெவ்வேறு மதிப்புகளைப் பயன்படுத்தலாம்.','Allow customers to checkout without an account' => 'கணக்கு இல்லாமல் வாடிக்கையாளர்கள் பணம் செலுத்த அனுமதிக்கவும்','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => 'பணம் செலுத்தும் போது வாடிக்கையாளர்கள் கணக்கை உருவாக்கவோ அல்லது உள்நுழையவோ கேட்கப்படுவதைத் தவிர்க்க <strong>இது பரிந்துரைக்கப்படுகிறது</strong> , ஏனெனில் இது விற்பனை விகிதங்களைக் குறைக்கக்கூடும்.','When disabled, customers must log in or create an account to complete the purchase.' => 'செயலிழக்கச் செய்யப்பட்டிருக்கும்போது, கொள்முதலைப் பூர்த்தி செய்ய வாடிக்கையாளர்கள் உள்நுழைய வேண்டும் அல்லது ஒரு கணக்கை உருவாக்க வேண்டும்.','Login at checkout' => 'பணம் செலுத்தும் இடத்தில் உள்நுழையவும்','Enable log-in during checkout' => 'பணம் செலுத்தும் போது உள்நுழைவை இயக்கவும்','Show a link for returning customers to log in from the checkout page.' => 'மீண்டும் வரும் வாடிக்கையாளர்கள் செக்அவுட் பக்கத்திலிருந்து உள்நுழைவதற்கான இணைப்பைக் காண்பிக்கவும்.','Account creation' => 'கணக்கு உருவாக்கம்','Allow customers to create an account during checkout' => 'பணம் செலுத்தும் போது வாடிக்கையாளர்கள் கணக்கை உருவாக்க அனுமதிக்கவும்.','Allow customers to create an account from the My account page' => '&#39;எனது கணக்கு&#39; பக்கத்திலிருந்து வாடிக்கையாளர்கள் கணக்கை உருவாக்க அனுமதிக்கவும்.','Customers can register a new account from the My account page.' => 'வாடிக்கையாளர்கள் &#39;எனது கணக்கு&#39; பக்கத்திலிருந்து ஒரு புதிய கணக்கைப் பதிவு செய்துகொள்ளலாம்.','Username' => 'பயனர்பெயர்','Generate from customer\'s name' => 'வாடிக்கையாளரின் பெயரிலிருந்து உருவாக்கவும்','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => 'பணம் செலுத்தும் போது வாடிக்கையாளர்கள் பயனர்பெயரைத் தேர்ந்தெடுக்கக் கேட்கப்படுவதைத் தவிர்க்க <strong>இது பரிந்துரைக்கப்படுகிறது</strong> , ஏனெனில் இது விற்பனை விகிதங்களைக் குறைக்கக்கூடும்.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'பயனர்பெயர் என்பது வாடிக்கையாளர் பெயரிலிருந்தோ, அல்லது பெயரைப் பயன்படுத்த முடியாத பட்சத்தில் மின்னஞ்சல் முகவரியிலிருந்தோ உருவாக்கப்படுகிறது.','Password' => 'கடவுச்சொல்','Send password setup link' => 'கடவுச்சொல் அமைவு இணைப்பை அனுப்பவும்','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => 'பணம் செலுத்தும் போது வாடிக்கையாளர்கள் கடவுச்சொல்லை அமைக்கக் கோரப்படுவதைத் தவிர்க்க <strong>இது பரிந்துரைக்கப்படுகிறது</strong> , ஏனெனில் இது விற்பனை மாற்ற விகிதங்களைக் குறைக்கக்கூடும்.','Customers receive an email to create their password securely.' => 'வாடிக்கையாளர்கள் தங்கள் கடவுச்சொல்லைப் பாதுகாப்பாக உருவாக்குவதற்காக ஓர் மின்னஞ்சலைப் பெறுவார்கள்.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'பதிவுசெய்யப்பட்ட வாடிக்கையாளர்கள் உள்நுழையாமலேயே பணம் செலுத்துதலை முடிக்கவும், தொடர்பு விவரங்கள் பொருந்தும்போது அந்த ஆர்டரை அவர்களின் தற்போதைய கணக்குடன் இணைக்கவும் அனுமதிக்கவும்.','Existing account message' => 'ஏற்கனவே உள்ள கணக்கு செய்தி','Let customers create an account after placing their order, from the thank you page.' => 'வாடிக்கையாளர்கள் தங்கள் ஆர்டரைப் பதிவுசெய்த பிறகு, நன்றிப் பக்கத்திலிருந்து ஒரு கணக்கை உருவாக்கிக்கொள்ள அனுமதிக்கவும்.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'விருந்தினர் செக்-அவுட் மற்றும் கணக்குப் பொருத்தம் ஆகியவை இயக்கப்பட்டிருக்கும்போது, இந்தப் பிரிவில் உள்ள விருப்பங்கள் கிடைக்கும். தாமதமான கணக்கு உருவாக்கத்தை உள்ளமைக்க, மேலே உள்ள இரண்டு அம்சங்களையும் இயக்கவும்.','Enable delayed account creation' => 'தாமதமான கணக்கு உருவாக்கத்தை இயக்கு','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'விருந்தினர் செக்-அவுட் மற்றும் கணக்குப் பொருத்தம் ஆகிய இரண்டும் இயக்கப்பட்டிருக்கும்போது, தாமதமான கணக்கு உருவாக்கத்தைச் செயல்படுத்தவும்.','Section position' => 'பிரிவு நிலை','Before customer details section' => 'வாடிக்கையாளர் விவரங்கள் பகுதிக்கு முன்','After customer details section' => 'வாடிக்கையாளர் விவரங்கள் பிரிவுக்குப் பிறகு','Account creation benefits' => 'கணக்கு உருவாக்கத்தின் நன்மைகள்','Leaving the field empty will display the default text.' => 'புலத்தை காலியாக விட்டால் இயல்புநிலை உரை காட்டப்படும்.','Inline buttons' => 'உள்ளமை பொத்தான்கள்','Required fields' => 'தேவையான புலங்கள்','Enable gift message fields at checkout' => 'செக் அவுட்டில் பரிசுச் செய்தி புலங்களைச் செயல்படுத்தவும்','Expanded gift message' => 'விரிவாக்கப்பட்ட பரிசுச் செய்தி','Display gift message field always expanded' => 'பரிசுச் செய்தி புலம் எப்போதும் விரிவடைந்த நிலையில் காட்டப்படும்.','Gift message in order details' => 'ஆர்டர் விவரங்களில் பரிசுச் செய்தி','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'தற்சமயம் இந்தப் பிரிவில் எந்த ஒருங்கிணைப்புகளும் கிடைக்கவில்லை. ஒவ்வொரு பிளகின் அல்லது தீம் செயல்படுத்தப்படும்போது மட்டுமே, அது தொடர்பான விருப்பத்தேர்வுகள் இங்கே தோன்றும்.','Phone fields' => 'தொலைபேசி புலங்கள்','Field visibility' => 'புலப் பார்வை','Field position' => 'புல நிலை','Phone country code & validation' => 'தொலைபேசி நாட்டுக் குறியீடு மற்றும் சரிபார்ப்பு','Country' => 'நாடு','Enable country on phone fields' => 'தொலைபேசி புலங்களில் நாட்டைச் செயல்படுத்து','Filter countries for shipping or billing' => 'அனுப்புதல் அல்லது பில்லிங்கிற்காக நாடுகளை வடிகட்டவும்','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'ஒவ்வொரு தொலைபேசி எண் புலத்திலும் உள்ள நாட்டுக் தேர்வியை, உங்கள் கடையில் அனுப்புவதற்கோ அல்லது கட்டணம் வசூலிப்பதற்கோ அனுமதிக்கப்பட்ட நாடுகளுக்கு மட்டும் வரம்பிடவும்.','Validation' => 'சரிபார்ப்பு','Enable simple validation based on country rules' => 'நாட்டு விதிகளின் அடிப்படையில் எளிய சரிபார்ப்பை இயக்கு','Checks that the phone number is valid for the selected country, including country code and length.' => 'தேர்ந்தெடுக்கப்பட்ட நாட்டிற்கு தொலைபேசி எண் செல்லுபடியாகிறதா என்பதை, நாட்டுக் குறியீடு மற்றும் கால அளவு உட்பட, சரிபார்க்கிறது.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'தேர்ந்தெடுக்கப்பட்ட நாட்டிற்குரிய செல்லுபடியாகும் மொபைல், நிலையான தொலைபேசி அல்லது பிற ஏற்றுக்கொள்ளப்பட்ட வகை எண் தானா என்பதை கடுமையாகச் சரிபார்க்க வேண்டும். சில செல்லுபடியாகும் எண்கள் நிராகரிக்கப்படலாம்.','Validation types' => 'சரிபார்ப்பு வகைகள்','Placeholders' => 'இடங்களுக்கானவை','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'தற்சமயம் நிர்வகிக்க உரிமச் சாவிகள் எதுவும் இல்லை. உரிமம் பெற்ற Fluid Checkout செருகுநிரல் அல்லது துணை நிரல் செயலில் இருக்கும்போது உரிமச் சாவிகள் இங்கே தோன்றும்.','Default delivery type' => 'இயல்புநிலை விநியோக வகை','Choose which delivery type will be selected by default.' => 'இயல்புநிலையாக எந்த விநியோக வகை தேர்ந்தெடுக்கப்பட வேண்டும் என்பதைத் தேர்வுசெய்யவும்.','Shipping zone fields' => 'கப்பல் மண்டல புலங்கள்','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'உள்ளூர் பிக்கப் ஷிப்பிங் மண்டல வடிகட்டிப் புலங்களில் எவை காட்டப்பட வேண்டும் என்பதைத் தேர்ந்தெடுக்கவும். கிடைக்கக்கூடிய அனைத்து விருப்பங்களையும் காட்ட, இதை காலியாக விடவும்.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'உள்ளூர் பிக்கப் ஷிப்பிங் முறைகளுக்கான வடிகட்டியாக இந்தப் புலங்கள் காட்டப்படும். இணக்கமான செருகுநிரல்கள் சரியாகச் செயல்பட சில புலங்கள் தேவைப்பட்டால், இங்கு தேர்ந்தெடுக்கப்படாதபோதும் அவை செக்அவுட்டின்போது தோன்றக்கூடும்.','Order shipping address' => 'ஆர்டர் அனுப்பும் முகவரி','Order pay page optimization' => 'ஆர்டர் கட்டணப் பக்க மேம்படுத்தல்','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'பணம் செலுத்தப்படாத ஆர்டர்களுக்கும், செக்அவுட்டைப் போலவே தெளிவான, விற்பனையை அதிகரிக்கும் தளவமைப்பை வழங்குங்கள்.','Optimize the layout of the order pay page for orders pending payment.' => 'பணம் செலுத்தப்படாமல் நிலுவையில் உள்ள ஆர்டர்களுக்கான கட்டணப் பக்கத்தின் வடிவமைப்பை மேம்படுத்தவும்.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'ஒரு சீரான கொள்முதல் அனுபவத்தைப் பெற, ஆர்டர் செலுத்தும் முறையை உங்கள் பரிவர்த்தனை முறையுடன் பொருத்துங்கள்.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'வாடிக்கையாளர்கள் பணம் செலுத்துவதற்கு முன் உறுதி தேவைப்படும் இடங்களில் நம்பிக்கைச் சின்னங்களையும் பேட்ஜ்களையும் சேர்க்கவும்.','Thank you page optimization' => 'நன்றி பக்க மேம்படுத்தல்','Make the thank you page and order details clearer for customers after they buy.' => 'வாடிக்கையாளர்கள் பொருளை வாங்கிய பிறகு, அவர்களுக்கு நன்றிப் பக்கத்தையும் ஆர்டர் விவரங்களையும் மேலும் தெளிவாகக் காட்டுங்கள்.','Optimize the thank you page and account order details with a clearer layout.' => 'நன்றிப் பக்கம் மற்றும் கணக்கு ஆர்டர் விவரங்களைத் தெளிவான வடிவமைப்புடன் மேம்படுத்துங்கள்.','Show order status progress, actions, downloads, and notes where they make sense.' => 'ஆர்டர் நிலை, முன்னேற்றம், செயல்பாடுகள், பதிவிறக்கங்கள் மற்றும் குறிப்புகளைப் பொருத்தமான இடங்களில் காண்பிக்கவும்.','Customize order details sections on email notifications.' => 'மின்னஞ்சல் அறிவிப்புகளில் உள்ள ஆர்டர் விவரப் பிரிவுகளைத் தனிப்பயனாக்கவும்.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'வாடிக்கையாளர்கள் பொருளை வாங்கிய பிறகு அவர்களுக்கு உறுதி தேவைப்படும் இடங்களில், நம்பிக்கைச் சின்னங்களையும் பேட்ஜ்களையும் சேர்க்கவும்.','Email notifications' => 'மின்னஞ்சல் அறிவிப்புகள்','Enable thank you page and order details optimizations to see more options' => 'கூடுதல் விருப்பங்களைக் காண, நன்றிப் பக்கம் மற்றும் ஆர்டர் விவரங்கள் மேம்படுத்தல்களைச் செயல்படுத்தவும்.','Use wide layout on thank you page' => 'நன்றிப் பக்கத்தில் அகலமான தளவமைப்பைப் பயன்படுத்தவும்','These options affect the thank you page, view order details on account pages and on email notifications.' => 'இந்த விருப்பங்கள் நன்றி தெரிவிக்கும் பக்கம், கணக்குப் பக்கங்களில் உள்ள ஆர்டர் விவரங்களைக் காண்பது மற்றும் மின்னஞ்சல் அறிவிப்புகள் ஆகியவற்றைப் பாதிக்கின்றன.','Save settings' => 'அமைப்புகளைச் சேமிக்கவும்','Docs' => 'ஆவணங்கள்','Cart' => 'வண்டி','Thank you' => 'நன்றி','Address autocomplete' => 'முகவரி தானியங்கு நிரப்புதல்','Trust badges' => 'நம்பிக்கை சின்னங்கள்','You do not have permission to save these settings.' => 'இந்த அமைப்புகளைச் சேமிக்க உங்களுக்கு அனுமதி இல்லை.','Invalid save request.' => 'செல்லாத சேமிப்புக் கோரிக்கை.','Your settings have been saved.' => 'உங்கள் அமைப்புகள் சேமிக்கப்பட்டுவிட்டன.','Saving...' => 'சேமிப்பு...','Settings could not be saved. Please try again.' => 'அமைப்புகளைச் சேமிக்க முடியவில்லை. மீண்டும் முயற்சிக்கவும்.','Dismiss notice' => 'அறிவிப்பை நிராகரி','Open settings menu' => 'அமைப்புகள் மெனுவைத் திறக்கவும்','Close settings menu' => 'அமைப்புகள் மெனுவை மூடுக','Preview' => 'முன்னோட்டம்','Expand preview' => 'முன்னோட்டத்தை விரிவாக்கு','Collapse preview' => 'சுருக்க முன்னோட்டம்','Show header and footer' => 'தலைப்பு மற்றும் அடிக்குறிப்பைக் காட்டு','Hide header and footer' => 'தலைப்பு மற்றும் அடிக்குறிப்பை மறைக்கவும்','Page preview' => 'பக்க முன்னோட்டம்','Preview viewport' => 'முன்னோட்டக் காட்சிப்பகுதி','Tablet' => 'டேப்லெட்','Desktop' => 'டெஸ்க்டாப்','Preview width' => 'முன்னோட்ட அகலம்','Decrease width' => 'அகலத்தைக் குறைக்கவும்','Preview width in pixels' => 'முன்னோட்ட அகலம் பிக்சல்களில்','Increase width' => 'அகலத்தை அதிகரிக்கவும்','Preview as' => 'முன்னோட்டம்','Guest' => 'விருந்தினர்','Logged in' => 'உள்நுழைந்தார்','Preview page' => 'முன்னோட்டப் பக்கம்','Expand preview for a closer look' => 'மேலும் விரிவாகப் பார்க்க முன்னோட்டத்தை விரிவாக்கவும்','Available with %s.' => '%s உடன் கிடைக்கிறது.','Turn them on' => 'அவற்றை இயக்கவும்','Optimizations for this page are turned off. %s to preview the page.' => 'இந்தப் பக்கத்திற்கான மேம்படுத்தல்கள் முடக்கப்பட்டுள்ளன. பக்கத்தை முன்னோட்டமிட %s ஐ அழுத்தவும்.','%s preview' => '%s முன்னோட்டம்','Isolated session · nothing is saved' => 'தனிமைப்படுத்தப்பட்ட அமர்வு · எதுவும் சேமிக்கப்படவில்லை','Usage tracking' => 'பயன்பாட்டைக் கண்காணித்தல்','Plugin settings' => 'செருகுநிரல் அமைப்புகள்','Coming soon' => 'விரைவில் வருகிறது','Utilities' => 'பயன்பாடுகள்','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => '<code>select2</code> க்கு பதிலாக <code>TomSelect</code> கீழ்விரிப் பட்டி கூறுகளைப் பயன்படுத்தவும்.','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect என்பது Select2-ஐ விடப் பிழைகள் ஏற்பட வாய்ப்பு குறைவான, அதே சமயம் அதே செயல்பாடுகளை வழங்கும் ஒரு எளிமையான கீழ்விரிப் பட்டியல் தேர்வுக் கூறு ஆகும்.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'சிறிய சாதனங்களில் படிவப் புலங்களுடன் தொடர்பு கொள்ளும்போது தானாகவே பெரிதாகுவதைத் தவிர்ப்பதற்காக, இந்தப் பிளகின் மூலம் மேம்படுத்தப்பட்ட பக்கங்களில் உள்ள படிவப் புலங்களின் எழுத்துரு அளவை 16px ஆக இது அமைக்கிறது.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'மொபைல் சாதனங்களில் எழுத்துரு அளவு 16px-ஐ விடச் சிறியதாக இருக்கும்போது, உரையை எளிதாகப் படிப்பதற்காக சஃபாரி மற்றும் பிற உலாவிகள் தானாகவே பெரிதாக்கக்கூடும்.','Enable script processing tracking on the browser console.' => 'உலாவி கன்சோலில் ஸ்கிரிப்ட் செயலாக்கக் கண்காணிப்பை இயக்கவும்.','Unminified assets' => 'குறைக்கப்படாத சொத்துக்கள்','Google Maps scripts' => 'கூகிள் மேப்ஸ் ஸ்கிரிப்டுகள்','Do not remove duplicate Google Maps scripts' => 'நகல் கூகுள் மேப்ஸ் ஸ்கிரிப்டுகளை அகற்ற வேண்டாம்','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'இதை இயக்கும்போது, நகல் கூகுள் மேப்ஸ் ஸ்கிரிப்டுகள் அகற்றப்படாது, இது பிழைகளையும் செயல்திறன் சிக்கல்களையும் ஏற்படுத்தக்கூடும். சிக்கல்களைத் தீர்க்கும்போது மட்டும் இந்த விருப்பத்தைப் பயன்படுத்தவும்.','Widget areas' => 'விட்ஜெட் பகுதிகள்','Last step on mobile' => 'மொபைலில் கடைசி படி','Display widgets only at last step on mobile' => 'மொபைலில் விட்ஜெட்களைக் கடைசிப் படியில் மட்டும் காண்பிக்கவும்','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'மொபைல் சாதனங்களில் கடைசிப் பரிவர்த்தனைப் படிநிலையைப் பார்க்கும்போது மட்டும், பரிவர்த்தனை நம்பிக்கைச் சின்ன விட்ஜெட்டுகளைக் காண்பிக்கவும்.','Standard' => 'தரநிலை','VAT number field' => 'VAT எண் புலம்','Add a VAT number field to the billing form.' => 'கட்டணப் படிவத்தில் VAT எண் புலத்தைச் சேர்க்கவும்.','Field label' => 'புல லேபிள்','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'VAT எண் புலத்தின் லேபிளை (அதாவது, VAT எண்) அமைக்கவும். பன்மொழி இணையதளங்களில், இந்தப் புலத்தைக் காலியாக விட்டுவிட்டு அசல் சரத்தை மொழிபெயர்ப்பது சிறந்தது.','VAT Number' => 'VAT எண்','EU-VAT' => 'ஐரோப்பிய ஒன்றிய மதிப்புக்கூட்டு வரி','Enable the VAT number field to see more options' => 'கூடுதல் விருப்பங்களைக் காண, VAT எண் புலத்தைச் செயல்படுத்தவும்.','VAT validation' => 'VAT சரிபார்ப்பு','Validate VAT number field for EU-VAT during checkout' => 'பணம் செலுத்தும் போது ஐரோப்பிய ஒன்றிய மதிப்புக்கூட்டு வரிக்கு (EU-VAT) மதிப்புக்கூட்டு வரி எண் புலத்தைச் சரிபார்க்கவும்.','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'வழங்கப்பட்ட VAT எண், ஐரோப்பிய VIES தரவுத்தளத்தில் (VAT தகவல் பரிமாற்ற அமைப்பு) பதிவுசெய்யப்பட்ட செல்லுபடியாகும் VAT எண் தானா என்பதைச் சரிபார்க்கிறது.','Shop VAT number' => 'கடை VAT எண்','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'ஐரோப்பிய ஒன்றிய மதிப்புக்கூட்டு வரி சரிபார்ப்பைக் கோருவதற்கும், விலைப்பட்டியல்களில் அச்சிடுவதற்கும் பயன்படுத்தப்படும் கடையின் மதிப்புக்கூட்டு வரி எண்.<br> <strong>உங்கள் கடை VAT எண்ணைச் சேர்க்குமாறு நாங்கள் வன்மையாகப் பரிந்துரைக்கிறோம்</strong> , இல்லையெனில் VIES கலந்தாய்வின் முடிவுகள் கணக்கியல் நோக்கங்களுக்காகச் செல்லுபடியாகாமல் போகலாம்.<br> அதாவது: <code>ATU99999999</code> அல்லது <code>EE999999999</code> .','Reverse charge' => 'எதிர் மின்னூட்டம்','Apply reverse charge mechanism' => 'எதிர் மின்னூட்ட வழிமுறையைப் பயன்படுத்துங்கள்','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'வாடிக்கையாளரின் VAT எண் செல்லுபடியாகும் பட்சத்தில், வரி விகிதத்தை பூஜ்ஜியமாக அமைத்து, விலைப்பட்டியல்களில் &quot;Reverse charge&quot; எனக் காண்பிக்கவும். கடையின் நாட்டைப் பொறுத்து, வேறுபட்ட &quot;Reverse charge&quot; வாசகம் தேவைப்படலாம்.','Same country' => 'அதே நாடு','Apply reverse charge mechanism for transactions in the shop country:' => 'கடை நடைபெறும் நாட்டில் நடைபெறும் பரிவர்த்தனைகளுக்கு எதிர் கட்டண முறையைப் பயன்படுத்துங்கள்:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'கடை அமைந்துள்ள அதே நாட்டில் உள்ள நிறுவனங்களுக்கு இடையேயான பரிவர்த்தனைகளுக்கு, எதிர் கட்டண முறையைப் பயன்படுத்த இது உதவுகிறது.','Reverse charge exceptions' => 'தலைகீழ் கட்டண விதிவிலக்குகள்','Select additional countries to skip applying the reverse charge mechanism.' => 'எதிர் கட்டண முறையைப் பயன்படுத்துவதைத் தவிர்க்க, கூடுதல் நாடுகளைத் தேர்ந்தெடுக்கவும்.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'சரியான VAT எண் வழங்கப்பட்டாலும், இந்த நாடுகளில் இருந்து வரும் ஆர்டர்களுக்கு வரிகள் விதிக்கப்படும்.','Reverse charge label on invoices' => 'விலைப்பட்டியல்களில் தலைகீழ் கட்டண லேபிள்','Set the label of "reverse charge" on the checkout page and order details.' => 'பணம் செலுத்தும் பக்கம் மற்றும் ஆர்டர் விவரங்களில் &quot;பணத்தைத் திரும்பப் பெறுதல்&quot; என்ற குறியீட்டை அமைக்கவும்.','Reverse charge text on invoices' => 'விலைப்பட்டியல்களில் உள்ள தலைகீழ் கட்டண உரை','Set the label of "reverse charge" text on invoices.' => 'விலைப்பட்டியல்களில் &quot;திரும்பக் கட்டணம்&quot; என்ற உரையின் லேபிளை அமைக்கவும்.','Tax to be paid on reverse charge basis' => 'தலைகீழ் கட்டண அடிப்படையில் வரி செலுத்தப்பட வேண்டும்','Company name' => 'நிறுவனத்தின் பெயர்','Autocomplete company name from VAT number' => 'VAT எண்ணிலிருந்து நிறுவனத்தின் பெயரைத் தானாக நிரப்பவும்','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'வாடிக்கையாளர் வழங்கிய செல்லுபடியாகும் VAT எண்ணின் அடிப்படையில் பில்லிங் நிறுவனத்தின் பெயரை நிரப்பவும்.','Company name editing' => 'நிறுவனத்தின் பெயர் திருத்தம்','Allow editing of auto-filled company name' => 'தானாக நிரப்பப்பட்ட நிறுவனத்தின் பெயரைத் திருத்த அனுமதிக்கவும்','When enabled, customers can change the company name associated with the provided VAT number.' => 'செயல்படுத்தப்படும்போது, வாடிக்கையாளர்கள் வழங்கப்பட்ட VAT எண்ணுடன் தொடர்புடைய நிறுவனத்தின் பெயரை மாற்றிக்கொள்ளலாம்.','EU-VAT for digital goods' => 'டிஜிட்டல் பொருட்களுக்கான ஐரோப்பிய ஒன்றிய மதிப்புக்கூட்டு வரி','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => '2015, ஜனவரி 1 முதல், டிஜிட்டல் பொருட்கள் தொடர்பான ஐரோப்பிய ஒன்றியத்தின் மதிப்புக்கூட்டு வரி (VAT) விதிமுறைகளில் மாற்றங்கள் செய்யப்பட்டுள்ளன. இந்த மாற்றங்கள் பிரத்தியேகமாக B2C பரிவர்த்தனைகளைப் பாதிக்கின்றன. டிஜிட்டல் பொருட்களுக்கான மதிப்புக்கூட்டு வரியானது, வாடிக்கையாளரின் இருப்பிடத்தின் அடிப்படையில் கணக்கிடப்பட வேண்டும். மேலும், இதற்கான ஆதாரங்கள் (IP முகவரி மற்றும் பில்லிங் முகவரி) சேகரிக்கப்பட வேண்டும்.','Tax classes for digital goods' => 'டிஜிட்டல் பொருட்களுக்கான வரி வகுப்புகள்','Select some tax classes' => 'சில வரி வகுப்புகளைத் தேர்ந்தெடுக்கவும்','Location evidence' => 'இருப்பிடச் சான்றுகள்','Collect customer\'s location evidence' => 'வாடிக்கையாளரின் இருப்பிட ஆதாரங்களைச் சேகரிக்கவும்','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'ஐபி முகவரியைச் சேமித்து, அதை வாடிக்கையாளரின் பில்லிங் முகவரியுடன் சரிபார்க்கிறது. வாடிக்கையாளரின் பில்லிங் முகவரி மற்றும் ஐபி முகவரியில் உள்ள நாடு பொருந்தவில்லை என்றால், அவர்கள் செக்அவுட் பக்கத்தில் உள்ள செக்பாக்ஸைத் தேர்வுசெய்து தங்கள் பில்லிங் முகவரியை உறுதிப்படுத்த வேண்டும்.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'இந்த விருப்பம் Fluid Checkout-இல் நிர்வகிக்கப்படுகிறது. <a href="%s">இதை வாடிக்கையாளர் கணக்கு அமைப்புகளில் மாற்றவும்</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'இந்த விருப்பம் Fluid Checkout-இல் நிர்வகிக்கப்படுகிறது. Fluid Checkout &gt; வாடிக்கையாளர் கணக்குகள் என்பதற்குள் சென்று இதை மாற்றவும்.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'இந்த விருப்பம் Fluid Checkout-இல் நிர்வகிக்கப்படுகிறது. Fluid Checkout செயல்படுத்தப்படும்போது, அனுப்பும் முகவரி எப்போதும் &quot;வாடிக்கையாளரின் அனுப்பும் முகவரிக்கு இயல்புநிலையாக&quot; என அமைக்கப்படும். வாடிக்கையாளர்கள் செக்அவுட்டின் போது வெவ்வேறு அனுப்பும் மற்றும் பில்லிங் முகவரிகளை வழங்கலாம்.<br><br> இயல்புநிலை பில்லிங் முகவரியை ஷிப்பிங் முகவரியைப் போலவே அமைப்பதற்கான ஒரு விருப்பம் <a href="%s">, Fluid Checkout அமைப்புகளில்</a> உள்ளது.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'இந்த விருப்பம் Fluid Checkout-இல் நிர்வகிக்கப்படுகிறது. Fluid Checkout செயல்படுத்தப்படும்போது, அனுப்பும் முகவரி எப்போதும் &quot;வாடிக்கையாளரின் அனுப்பும் முகவரிக்கு இயல்புநிலையாக&quot; என அமைக்கப்படும். வாடிக்கையாளர்கள் செக்அவுட்டின் போது வெவ்வேறு அனுப்பும் மற்றும் பில்லிங் முகவரிகளை வழங்கலாம்.<br><br> இயல்புநிலை பில்லிங் முகவரியை ஷிப்பிங் முகவரியைப் போலவே அமைப்பதற்கான ஒரு விருப்பம் WooCommerce &gt; Settings &gt; Fluid Checkout இல் கிடைக்கிறது.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'இந்த அமைப்புகள் WP Admin &gt; Fluid Checkout &gt; Settings என்பதற்கு மாற்றப்பட்டுள்ளன.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'இந்த WooCommerce அமைப்புகள் பகுதி வழக்கற்றுப் போயுள்ளது, மேலும் இது Fluid Checkout 6.0 பதிப்பில் நீக்கப்படும்.','Go to settings page' => 'அமைப்புகள் பக்கத்திற்குச் செல்லவும்','Hide this tab permanently' => 'இந்த தாவலை நிரந்தரமாக மறைக்கவும்','Close' => 'அருகில்','PRO feature' => 'புரோ அம்சம்','Other plugins' => 'பிற செருகுநிரல்கள்','Install add-on' => 'துணை நிரலை நிறுவவும்','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => 'இந்த விருப்பங்களைத் திறக்க <a target="_blank" href="%1$s">%2$ பெறுங்கள்</a> .','Add-on' => 'கூடுதல்','View documentation' => 'ஆவணங்களைக் காண்க','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'கோரிக்கைகளுக்கு உள்நுழைந்த வேர்ட்பிரஸ் பயனர் தேவை. தற்போதைய பயனரின் தரவைப் பயன்படுத்த user_id-ஐத் தவிர்க்கவும், அல்லது அழைப்பவரால் மற்றொரு பயனரைத் திருத்த முடிந்தால் (edit_user வசதி), அந்தக் கணக்கை இலக்காகக் கொள்ள user_id-ஐ அனுப்பவும். அங்கீகரிக்கப்படாத கோரிக்கைகள் fc_api_forbidden எனத் திருப்பியளிக்கும். தவறான user_id fc_api_user_not_found எனத் திருப்பியளிக்கும்.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'ஹேண்ட்லர் ஒரு பேலோடைத் திருப்பி அனுப்பும்போது, { &quot;data&quot;: { ... } } உடன் HTTP 200 பிழை காட்டப்படும்.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'பேலோட் (உதாரணமாக DELETE) இல்லாதபோது, { &quot;success&quot;: true } உடன் HTTP 200 காட்டப்படும்.','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'தோல்விகள் WP_Error இலிருந்து WordPress REST பிழை JSON ஐ (code, message, data.status) திருப்பி அனுப்புகின்றன. வயர் கோடுகள் fc_api_* முன்னொட்டைப் பயன்படுத்துகின்றன.','Forbidden access.' => 'அணுகல் தடைசெய்யப்பட்டுள்ளது.','Target user was not found.' => 'இலக்கு பயனர் கண்டறியப்படவில்லை.','This feature is not available.' => 'இந்த அம்சம் கிடைக்கவில்லை.','A required address field is missing.' => 'தேவையான முகவரிப் புலம் விடுபட்டுள்ளது.','Postcode or ZIP is invalid.' => 'அஞ்சல் குறியீடு அல்லது ZIP செல்லாது.','Phone number is invalid.' => 'தொலைபேசி எண் தவறானது.','State or county is invalid.' => 'மாநிலம் அல்லது மாவட்டம் என்பது செல்லாது.','Country is invalid or has no address fields.' => 'நாடு தவறானது அல்லது முகவரிப் புலங்கள் இல்லை.','The request could not be processed.' => 'கோரிக்கையைச் செயல்படுத்த முடியவில்லை.','Back to previous step' => 'முந்தைய படிக்குத் திரும்பு','Skip to settings' => 'அமைப்புகளுக்குச் செல்லவும்','Start over and return to the first guided setup step' => 'மீண்டும் தொடங்கி, வழிகாட்டப்பட்ட முதல் அமைவுப் படிக்குத் திரும்பவும்.','Start over' => 'மீண்டும் தொடங்கு','Please complete all sub-steps before continuing.' => 'தொடர்வதற்கு முன் அனைத்து துணைப் படிநிலைகளையும் நிறைவு செய்யவும்.','Expand' => 'விரிவாக்கு','Collapse' => 'சரிவு','Skip' => 'தவிர்க்கவும்','Mark as complete' => 'நிறைவுற்றதாகக் குறிக்கவும்','Mark as incomplete' => 'முழுமையற்றதாகக் குறிக்கவும்','View full-size image: %s' => 'முழு அளவுப் படத்தைக் காண்க: %s','Full-size setup guide image' => 'முழு அளவு அமைவு வழிகாட்டி படம்','Close image' => 'நெருக்கமான படம்','Fluid Checkout Guided Setup' => 'திரவ சரிபார்ப்பு வழிகாட்டப்பட்ட அமைப்பு','All set' => 'எல்லாம் தயார்','You do not have permission to access this page.' => 'இந்தப் பக்கத்தை அணுக உங்களுக்கு அனுமதி இல்லை.','Go to step %1$d: %2$s' => 'படி %1$d க்குச் செல்லவும்: %2$s','Finish & go to settings' => 'முடித்துவிட்டு அமைப்புகளுக்குச் செல்லவும்','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'பில்லிங் தொலைபேசி புலத்தின் தெரிவுநிலை விருப்பத்தை, பழைய மதிப்பிலிருந்து WooCommerce மரபுகளுக்கு ஏற்றவாறு புதுப்பிக்கவும்.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'WooCommerce மரபுகளுக்கு ஏற்ப, ஷிப்பிங் ஃபோன் ஃபீல்டின் தெரிவுநிலை விருப்பத்தை பழைய மதிப்பிலிருந்து புதுப்பிக்கவும்.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'ஆர்டர் சுருக்கப் பின்னணி வண்ண அமைப்பை, புதிய பிரிப்பு வடிவமைப்பு இரண்டாம் நிலை நெடுவரிசைப் பின்னணி வண்ண விருப்பத்திற்கு நகலெடுக்கவும்.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'பைட்ஷிப் செருகுநிரலைப் பயன்படுத்தும்போது, மேம்படுத்தப்பட்ட தேர்வுப் புலங்கள் அம்சம் எப்போதும் முடக்கப்பட்டிருக்கும்.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'ஜெர்மன் மார்க்கெட்டைப் பயன்படுத்தும்போது, ஆர்டர் செய்யும் நிலை எப்போதும் &quot;ஆர்டர் சுருக்கத்திற்குக் கீழே&quot; என அமைக்கப்படுகிறது. அந்த பிளகினுக்கு, ஆர்டர் செய்யும் பொத்தானும் சட்டப்பூர்வ சரிபார்ப்புப் பெட்டிகளும் ஆர்டர் சுருக்கத்திற்குக் கீழே காட்டப்பட வேண்டும்.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'WooCommerce-க்கான Germanized-ஐப் பயன்படுத்தும்போது, ஆர்டர் செய்யும் நிலை எப்போதும் &quot;ஆர்டர் சுருக்கத்திற்குக் கீழே&quot; என அமைக்கப்படுகிறது. அந்த பிளகினுக்கு, ஆர்டர் செய்யும் பொத்தானும் சட்டப்பூர்வ சரிபார்ப்புப் பெட்டிகளும் ஆர்டர் சுருக்கத்திற்குக் கீழே காட்டப்பட வேண்டும்.','Edit pickup locations' => 'பிக்கப் இடங்களைத் திருத்தவும்','Use local pickup label from WooCommerce settings' => 'WooCommerce அமைப்புகளிலிருந்து உள்ளூர் பிக்கப் லேபிளைப் பயன்படுத்தவும்','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'இயக்கப்பட்டிருக்கும்போது, செக் அவுட்டில் உள்ள பிக்கப் விருப்ப லேபிள், WooCommerce பிக்கப் இருப்பிட அமைப்புகளில் உள்ள தலைப்புடன் பொருந்தும். முடக்கப்பட்டிருக்கும்போது, அந்த லேபிள் Fluid Checkout-இல் உள்ள மொழிபெயர்க்கக்கூடிய &quot;உள்ளூர் பிக்கப்&quot; என்ற உரையைப் பயன்படுத்துகிறது.','Migration class %s must implement get_migration_steps().' => 'இடம்பெயர்வு வகுப்பு %s, get_migration_steps() என்பதைச் செயல்படுத்த வேண்டும்.','Migration class %s returned an empty get_migration_steps() list.' => 'இடம்பெயர்வு வகுப்பு %s, get_migration_steps() என்ற வெற்றுப் பட்டியலைத் திருப்பியளித்தது.','Checkout design customization' => 'வடிவமைப்பு தனிப்பயனாக்கத்தைப் பார்க்கவும்','Make your checkout pages match your brand, without custom CSS.' => 'தனிப்பயன் CSS இல்லாமல், உங்கள் செக்அவுட் பக்கங்களை உங்கள் பிராண்டுக்கு ஏற்றவாறு மாற்றுங்கள்.','Change the style of the header, footer, steps, sections, order summary, cart items and coupons.' => 'தலைப்பு, அடிக்குறிப்பு, படிநிலைகள், பிரிவுகள், ஆர்டர் சுருக்கம், கார்ட் பொருட்கள் மற்றும் கூப்பன்களின் பாணியை மாற்றவும்.','Change the style of buttons and form fields.' => 'பொத்தான்கள் மற்றும் படிவப் புலங்களின் பாணியை மாற்றவும்.','Preview your changes on checkout, cart, thank you, and order pay pages before saving them.' => 'உங்கள் மாற்றங்களைச் சேமிப்பதற்கு முன், செக்அவுட், கார்ட், நன்றி மற்றும் ஆர்டர் கட்டணப் பக்கங்களில் அவற்றை முன்னோட்டமிட்டுப் பார்க்கவும்.','Set separate colors for light and dark mode.' => 'ஒளி மற்றும் இருண்ட பயன்முறைகளுக்குத் தனித்தனி வண்ணங்களை அமைக்கவும்.','Design' => 'வடிவமைப்பு','Some changes to the database are required.' => 'தரவுத்தளத்தில் சில மாற்றங்கள் தேவைப்படுகின்றன.','New settings page 🎉' => 'புதிய அமைப்புகள் பக்கம் 🎉','Fluid Checkout has a redesigned settings experience with guided setup, live page previews, and easier navigation. Open settings to explore the new layout and discover new ways to configure your checkout.' => 'ஃப்ளூயிட் செக்அவுட், வழிகாட்டப்பட்ட அமைப்பு, நேரலைப் பக்க முன்னோட்டங்கள் மற்றும் எளிதான வழிசெலுத்தல் ஆகியவற்றுடன் மறுவடிவமைக்கப்பட்ட அமைப்புகள் அனுபவத்தைக் கொண்டுள்ளது. புதிய தளவமைப்பை ஆராயவும், உங்கள் செக்அவுட்டை உள்ளமைப்பதற்கான புதிய வழிகளைக் கண்டறியவும் அமைப்புகளைத் திறக்கவும்.','Go to settings' => 'அமைப்புகளுக்குச் செல்லவும்','Since Fluid Checkout 5.0, settings are saved differently. Your settings have been migrated but legacy options are still stored in the database.' => 'Fluid Checkout 5.0 முதல், அமைப்புகள் வேறு விதமாகச் சேமிக்கப்படுகின்றன. உங்கள் அமைப்புகள் இடம்பெயர்ந்துவிட்டன, ஆனால் பழைய விருப்பத்தேர்வுகள் இன்னும் தரவுத்தளத்தில் சேமிக்கப்பட்டுள்ளன.','Your store has been running for at least 2 months on the new settings so these legacy options can now be cleaned from the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'உங்கள் ஸ்டோர் புதிய அமைப்புகளில் குறைந்தது 2 மாதங்களாக இயங்கி வருவதால், இந்தப் பழைய விருப்பங்களை இப்போது தரவுத்தளத்திலிருந்து நீக்கலாம். இந்தச் சுத்திகரிப்புக்குப் பிறகு, நீங்கள் பிளகினின் முந்தைய பதிப்புகளுக்குத் தரமிறக்க நேர்ந்தால், அது அனைத்து அமைப்புகளுக்கும் இயல்புநிலை மதிப்புகளையே பயன்படுத்தும் என்பதை நினைவில் கொள்ளவும்.','Fluid Checkout legacy settings cleanup' => 'ஃப்ளூயிட் செக்அவுட் மரபு அமைப்புகளைச் சுத்தம் செய்தல்','Usage tracking is optional and off by default. It helps us improve compatibility and support. You can preview the exact data before it is sent, and turn it off at any time.' => 'பயன்பாட்டைக் கண்காணிப்பது விருப்பத்தேர்வு மற்றும் இயல்பாகவே முடக்கப்பட்டுள்ளது. இது இணக்கத்தன்மையையும் ஆதரவையும் மேம்படுத்த எங்களுக்கு உதவுகிறது. தரவு அனுப்பப்படுவதற்கு முன்பு அதன் சரியான வடிவத்தை நீங்கள் முன்னோட்டமிடலாம், மேலும் எப்போது வேண்டுமானாலும் அதை முடக்கலாம்.','When you turn it on, Fluid Checkout receives your site domain and basic environment details: WordPress, PHP and WooCommerce versions, language, store country, currency and timezone, your active theme, and your installed plugins and their versions. You can also choose to include monthly order counts and sales totals. No customer or user data is ever sent.' => 'நீங்கள் இதை இயக்கும்போது, Fluid Checkout உங்கள் தளத்தின் டொமைன் மற்றும் அடிப்படைச் சூழல் விவரங்களான WordPress, PHP மற்றும் WooCommerce பதிப்புகள், மொழி, கடை அமைந்துள்ள நாடு, நாணயம் மற்றும் நேர மண்டலம், நீங்கள் செயலில் வைத்திருக்கும் தீம், மற்றும் நீங்கள் நிறுவியுள்ள செருகுநிரல்கள் மற்றும் அவற்றின் பதிப்புகள் ஆகியவற்றைப் பெறுகிறது. மாதாந்திர ஆர்டர் எண்ணிக்கை மற்றும் மொத்த விற்பனைத் தொகைகளையும் சேர்க்க நீங்கள் தேர்வு செய்யலாம். வாடிக்கையாளர் அல்லது பயனர் தரவுகள் எதுவும் ஒருபோதும் அனுப்பப்படுவதில்லை.','Keep it OFF' => 'அதை அணைத்து வைக்கவும்','Review usage tracking' => 'பயன்பாட்டு கண்காணிப்பை மதிப்பாய்வு செய்யவும்','Turn on usage tracking' => 'பயன்பாட்டைக் கண்காணிப்பதை இயக்குகிறது','Design customizations without code' => 'குறியீடு இல்லாமல் வடிவமைப்பு தனிப்பயனாக்கங்கள்','Express checkout from supported payment methods' => 'ஆதரிக்கப்படும் கட்டண முறைகள் மூலம் விரைவான பணம் செலுத்துதல்','Choose a color for %s' => '%s-க்கு ஒரு நிறத்தைத் தேர்ந்தெடுக்கவும்','Clear %s' => '%s-ஐ அழிக்கவும்','Clear' => 'தெளிவான','Enter a valid CSS value.' => 'சரியான CSS மதிப்பை உள்ளிடவும்.','Get faster support and help us improve compatibility and measure impact. Usage tracking is optional and off by default. <a href="%s">Review usage tracking</a> in the tools settings. You can preview the data and turn it off at any time.' => 'விரைவான ஆதரவைப் பெறுங்கள், மேலும் இணக்கத்தன்மையை மேம்படுத்தவும் தாக்கத்தை அளவிடவும் எங்களுக்கு உதவுங்கள். பயன்பாட்டைக் கண்காணிப்பது விருப்பத்தேர்வு மற்றும் இயல்பாகவே முடக்கப்பட்டுள்ளது. கருவிகளின் அமைப்புகளில் <a href="%s">பயன்பாட்டைக் கண்காணிப்பதை மதிப்பாய்வு செய்யவும்</a> . நீங்கள் தரவை முன்னோட்டமிடலாம் மற்றும் எந்த நேரத்திலும் அதை முடக்கலாம்.','Preview data' => 'முன்னோட்டத் தரவு','General styles for the checkout steps, order summary and other sections. Applies to the checkout and add payment method pages. With PRO, also applies to the cart, order pay, thank you (order received) and view order pages.' => 'பணம் செலுத்தும் வழிமுறைகள், ஆர்டர் சுருக்கம் மற்றும் பிற பிரிவுகளுக்கான பொதுவான பாணிகள். இது பணம் செலுத்தும் முறை மற்றும் பணம் செலுத்தும் முறையைச் சேர்க்கும் பக்கங்களுக்குப் பொருந்தும். PRO பதிப்பில், இது கார்ட், ஆர்டர் பணம் செலுத்துதல், நன்றி (ஆர்டர் பெறப்பட்டது) மற்றும் ஆர்டரைப் பார்க்கும் பக்கங்களுக்கும் பொருந்தும்.','Color scheme' => 'வண்ணத் திட்டம்','Use the light or dark colors on the checkout pages, or use the dark colors only when the theme is in dark mode.' => 'பணம் செலுத்தும் பக்கங்களில் வெளிர் அல்லது அடர் வண்ணங்களைப் பயன்படுத்துங்கள், அல்லது தீம் டார்க் மோடில் இருக்கும்போது மட்டும் அடர் வண்ணங்களைப் பயன்படுத்துங்கள்.','Theme' => 'தீம்','Light' => 'ஒளி','Dark' => 'இருள்','Change the checkout layout to multi-step to see these options.' => 'இந்த விருப்பங்களைக் காண, பணம் செலுத்தும் முறையை பல படிநிலைகளாக மாற்றவும்.','Display the checkout progress bar' => 'பணம் செலுத்தும் முன்னேற்றப் பட்டையைக் காண்பி','Customers can create an account from checkout while placing their order.' => 'வாடிக்கையாளர்கள் தங்களது ஆர்டரைப் பதிவுசெய்யும்போது, பணம் செலுத்தும் பகுதியிலேயே ஒரு கணக்கை உருவாக்கிக்கொள்ளலாம்.','Help guests finish checkout faster and create an account after they buy. Account matching associates guest orders with existing accounts, and delayed account creation lets customers register from the thank you page.' => 'விருந்தினர்கள் விரைவாகப் பணம் செலுத்தி முடிக்கவும், வாங்கிய பிறகு ஒரு கணக்கை உருவாக்கவும் உதவுங்கள். கணக்குப் பொருத்தம், விருந்தினர்களின் ஆர்டர்களை ஏற்கனவே உள்ள கணக்குகளுடன் இணைக்கிறது, மேலும் தாமதமான கணக்கு உருவாக்கம், வாடிக்கையாளர்களை நன்றிப் பக்கத்திலிருந்தே பதிவுசெய்ய அனுமதிக்கிறது.','Configure customer account options' => 'வாடிக்கையாளர் கணக்கு விருப்பங்களை உள்ளமைக்கவும்','The change could not be saved. Please try again.' => 'மாற்றத்தைச் சேமிக்க முடியவில்லை. மீண்டும் முயற்சிக்கவும்.','Settings navigation' => 'அமைப்புகள் வழிசெலுத்தல்','This setting has moved to %s.' => 'இந்த அமைப்பு %s க்கு மாற்றப்பட்டுள்ளது.','another page' => 'மற்றொரு பக்கம்','Dismiss the message of %s' => '%s இன் செய்தியை நிராகரிக்கவும்','Dismissed.' => 'தள்ளுபடி செய்யப்பட்டது.','Undo?' => 'செயல்தவிர்க்கவா?','Optional, and off by default. It helps us improve compatibility and provide you with faster support. You can preview the exact data before it is sent, and turn it off at any time. No customer or user data is ever sent.' => 'இது விருப்பத்திற்குட்பட்டது, மற்றும் இயல்பாகவே முடக்கப்பட்டுள்ளது. இது இணக்கத்தன்மையை மேம்படுத்தவும், உங்களுக்கு விரைவான ஆதரவை வழங்கவும் எங்களுக்கு உதவுகிறது. தரவு அனுப்பப்படுவதற்கு முன்பு அதன் சரியான வடிவத்தை நீங்கள் முன்னோட்டமிடலாம், மேலும் எப்போது வேண்டுமானாலும் இதை முடக்கலாம். வாடிக்கையாளர் அல்லது பயனர் தரவுகள் எதுவும் ஒருபோதும் அனுப்பப்படுவதில்லை.','Nothing is sent right away unless you choose to send it. After that, usage data is sent about once a week, or about every 4 weeks if nothing has changed.' => 'நீங்கள் அனுப்பத் தேர்வுசெய்தால் தவிர, எதுவும் உடனடியாக அனுப்பப்படாது. அதன்பிறகு, பயன்பாட்டுத் தரவுகள் வாரத்திற்கு ஒருமுறை அல்லது எதுவும் மாறவில்லை என்றால் சுமார் 4 வாரங்களுக்கு ஒருமுறை அனுப்பப்படும்.','Basic environment' => 'அடிப்படை சூழல்','Included whenever usage tracking is on. WordPress, PHP and WooCommerce versions, language, store country, currency and timezone, your active theme, and your installed plugins and their versions, including whether each plugin is active. Also your site domain, whether this is a multisite, and when Fluid Checkout plugins were first activated. A paid Fluid Checkout plugin can include a hashed license key, not the key itself.' => 'பயன்பாட்டைக் கண்காணிக்கும் வசதி இயக்கப்பட்டிருக்கும் போதெல்லாம் இவை சேர்க்கப்படும். வேர்ட்பிரஸ், பிஎச்பி மற்றும் வூகாமர்ஸ் பதிப்புகள், மொழி, கடை அமைந்துள்ள நாடு, நாணயம் மற்றும் நேர மண்டலம், நீங்கள் செயலில் வைத்திருக்கும் தீம், மற்றும் நீங்கள் நிறுவியுள்ள பிளகின்கள் மற்றும் அவற்றின் பதிப்புகள், ஒவ்வொரு பிளகினும் செயலில் உள்ளதா என்பது உட்பட. மேலும் உங்கள் தளத்தின் டொமைன், இது ஒரு மல்டிசைட்டா என்பது, மற்றும் Fluid Checkout பிளகின்கள் முதன்முதலில் எப்போது செயல்படுத்தப்பட்டன என்பதும் இதில் அடங்கும். கட்டணம் செலுத்திப் பெறும் Fluid Checkout பிளகினில், உரிமச் சாவிக்கு பதிலாக, ஒரு ஹாஷ் செய்யப்பட்ட உரிமச் சாவி இருக்கலாம்.','The active Fluid Checkout settings you have selected.' => 'நீங்கள் தேர்ந்தெடுத்த செயலில் உள்ள திரவ சரிபார்ப்பு அமைப்புகள்.','These settings are not sent yet.' => 'இந்த அமைப்புகள் இன்னும் அனுப்பப்படவில்லை.','Store totals' => 'கடை மொத்தங்கள்','Monthly order counts and sales totals for processing and completed orders, for finished months only. The first send can include the 12 months before you installed Fluid Checkout and each finished month since then. No customer or order details are included.' => 'முடிந்த மாதங்களுக்கு மட்டும், செயலாக்கத்தில் உள்ள மற்றும் முடிக்கப்பட்ட ஆர்டர்களுக்கான மாதாந்திர ஆர்டர் எண்ணிக்கைகள் மற்றும் விற்பனைத் தொகைகள். முதல் அனுப்பலில், நீங்கள் Fluid Checkout-ஐ நிறுவுவதற்கு முந்தைய 12 மாதங்களும், அதன் பிறகு முடிந்த ஒவ்வொரு மாதமும் சேர்க்கப்படலாம். வாடிக்கையாளர் அல்லது ஆர்டர் விவரங்கள் எதுவும் சேர்க்கப்படவில்லை.','Legacy settings' => 'மரபு அமைப்புகள்','Since Fluid Checkout 5.0, settings are stored in profiles. Legacy individual option rows may still exist in the database from older versions to allow downgrades to a pre-5.0 plugin version.' => 'Fluid Checkout 5.0 முதல், அமைப்புகள் சுயவிவரங்களில் சேமிக்கப்படுகின்றன. 5.0-க்கு முந்தைய செருகுநிரல் பதிப்பிற்குத் தரமிறக்குவதை அனுமதிப்பதற்காக, பழைய பதிப்புகளிலிருந்து மரபுவழித் தனிப்பட்ட விருப்ப வரிசைகள் தரவுத்தளத்தில் இன்னும் இருக்கலாம்.','Legacy settings cleanup' => 'மரபு அமைப்புகளைச் சுத்தம் செய்தல்','Remove leftover individual option rows after you no longer need to downgrade to a pre-5.0 plugin version.' => '5.0-க்கு முந்தைய பிளகின் பதிப்பிற்குத் தரமிறக்க வேண்டிய தேவை இல்லாத பிறகு, மீதமுள்ள தனிப்பட்ட விருப்ப வரிசைகளை நீக்கிவிடவும்.','Clean legacy settings' => 'சுத்தமான மரபு அமைப்புகள்','Address book integration' => 'முகவரிப் புத்தக ஒருங்கிணைப்பு','VAT number' => 'VAT எண்','Define limit of VAT Numbers a customer can save to their account.' => 'ஒரு வாடிக்கையாளர் தனது கணக்கில் சேமிக்கக்கூடிய VAT எண்களின் வரம்பை வரையறுக்கவும்.','One per account' => 'ஒரு கணக்கிற்கு ஒன்று','Usage data preview' => 'பயன்பாட்டுத் தரவு முன்னோட்டம்','This is the exact usage data that would be sent with your current choices.' => 'உங்கள் தற்போதைய தேர்வுகளுடன் அனுப்பப்படும் துல்லியமான பயன்பாட்டுத் தரவு இதுவே ஆகும்.','Loading preview...' => 'முன்னோட்டம் ஏற்றப்படுகிறது...','Could not load the preview. Try again.' => 'முன்னோட்டத்தை ஏற்ற முடியவில்லை. மீண்டும் முயற்சிக்கவும்.','Could not send the usage data. Try again.' => 'பயன்பாட்டுத் தரவை அனுப்ப முடியவில்லை. மீண்டும் முயற்சிக்கவும்.','Usage data sent.' => 'பயன்பாட்டுத் தரவு அனுப்பப்பட்டது.','Turn on and send now' => 'இப்போது இயக்கி அனுப்பவும்','Usage data is already being sent. Try again in a moment.' => 'பயன்பாட்டுத் தரவு ஏற்கனவே அனுப்பப்பட்டு வருகிறது. சிறிது நேரத்தில் மீண்டும் முயற்சிக்கவும்.','Usage tracking is turned off.' => 'பயன்பாட்டைக் கண்காணிப்பது முடக்கப்பட்டுள்ளது.','There is no usage data to send.' => 'அனுப்புவதற்குப் பயன்பாட்டுத் தரவுகள் எதுவும் இல்லை.','This site cannot send usage data. Local and development sites are excluded.' => 'இந்தத் தளத்தால் பயன்பாட்டுத் தரவை அனுப்ப இயலாது. உள்ளூர் மற்றும் மேம்பாட்டுத் தளங்கள் இதற்கு விதிவிலக்கு.','Usage data was sent recently. Try again later.' => 'பயன்பாட்டுத் தரவு சமீபத்தில் அனுப்பப்பட்டது. பின்னர் மீண்டும் முயற்சிக்கவும்.','The usage data could not be sent. Try again later.' => 'பயன்பாட்டுத் தரவை அனுப்ப முடியவில்லை. பின்னர் மீண்டும் முயற்சிக்கவும்.','Usage tracking is not available.' => 'பயன்பாட்டைக் கண்காணிக்கும் வசதி இல்லை.','There is no usage data for these choices.' => 'இந்தத் தேர்வுகளுக்கான பயன்பாட்டுத் தரவுகள் எதுவும் இல்லை.','You are not allowed to manage usage tracking.' => 'பயன்பாட்டைக் கண்காணிப்பதை நிர்வகிக்க உங்களுக்கு அனுமதி இல்லை.','Get only this add-on' => 'இந்த கூடுதல் அம்சத்தை மட்டும் பெறுங்கள்','Usage tracking is turned off by the %s constant in wp-config.php.' => 'wp-config.php இல் உள்ள %s மாறிலியின் மூலம் பயன்பாட்டைக் கண்காணிப்பது முடக்கப்பட்டுள்ளது.','Physical products' => 'இயற்பியல் பொருட்கள்','Downloads & Digital products' => 'பதிவிறக்கங்கள் மற்றும் டிஜிட்டல் தயாரிப்புகள்','Services' => 'சேவைகள்','Bookings' => 'முன்பதிவுகள்','Subscriptions' => 'சந்தாக்கள்','Memberships' => 'உறுப்பினர் சேர்க்கைகள்','Shipping to address' => 'அனுப்ப வேண்டிய முகவரி','Pickup in store or at a location' => 'கடையில் அல்லது ஒரு குறிப்பிட்ட இடத்தில் பெற்றுக்கொள்ளவும்','Ship to pickup point' => 'பொருட்களைப் பெற்றுக்கொள்ளும் இடத்திற்கு அனுப்பவும்','Local delivery' => 'உள்ளூர் விநியோகம்','DTC - Direct to consumer' => 'DTC - நுகர்வோருக்கு நேரடியாக','B2B - To businesses' => 'பி2பி - வணிகங்களுக்கு','your country' => 'உங்கள் நாடு','Only in %s' => '%களில் மட்டும்','Multiple countries' => 'பல நாடுகள்','Fashion, apparel, and accessories' => 'ஃபேஷன், ஆடைகள் மற்றும் அணிகலன்கள்','Health and beauty' => 'ஆரோக்கியம் மற்றும் அழகு','Electronics and computers' => 'மின்னணுவியல் மற்றும் கணினிகள்','Food and drink' => 'உணவு மற்றும் பானம்','Home, furniture, and garden' => 'வீடு, தளபாடங்கள் மற்றும் தோட்டம்','Education and learning' => 'கல்வி மற்றும் கற்றல்','Sports and recreation' => 'விளையாட்டு மற்றும் பொழுதுபோக்கு','Arts and crafts' => 'கலை மற்றும் கைவினைப்பொருட்கள்','Other' => 'மற்றவை','Please select what type of products or services you sell.' => 'நீங்கள் என்ன வகையான பொருட்கள் அல்லது சேவைகளை விற்கிறீர்கள் என்பதைத் தேர்ந்தெடுக்கவும்.','Please select who you sell to.' => 'நீங்கள் யாருக்கு விற்பனை செய்கிறீர்கள் என்பதைத் தேர்ந்தெடுக்கவும்.','Please select where your customers are located.' => 'உங்கள் வாடிக்கையாளர்கள் எங்குள்ளனர் என்பதைத் தேர்ந்தெடுக்கவும்.','Please enter a valid email address for the newsletter.' => 'செய்திமடலுக்காக சரியான மின்னஞ்சல் முகவரியை உள்ளிடவும்.','Please select at least one product type.' => 'தயவுசெய்து குறைந்தபட்சம் ஒரு தயாரிப்பு வகையைத் தேர்ந்தெடுக்கவும்.','Please select at least one delivery method for physical products.' => 'பௌதீகப் பொருட்களுக்குக் குறைந்தபட்சம் ஒரு விநியோக முறையையாவது தேர்ந்தெடுக்கவும்.','About your store' => 'உங்கள் கடையைப் பற்றி','Products & delivery' => 'பொருட்கள் மற்றும் விநியோகம்','Recommended setup' => 'பரிந்துரைக்கப்பட்ட அமைப்பு','Show recommendations already applied' => 'ஏற்கனவே செயல்படுத்தப்பட்ட பரிந்துரைகளைக் காட்டு','Hide recommendations already applied' => 'மறைப்புப் பரிந்துரைகள் ஏற்கனவே செயல்படுத்தப்பட்டுவிட்டன.','Show more recommendations' => 'மேலும் பரிந்துரைகளைக் காட்டு','Show fewer recommendations' => 'குறைவான பரிந்துரைகளைக் காட்டு','Welcome to Fluid Checkout!' => 'ஃப்ளூயிட் செக்அவுட்டிற்கு வரவேற்கிறோம்!','It is great to have you here with us! We will be guiding you through the setup process – your answers to a few questions will help us recommend checkout settings for your store.' => 'நீங்கள் எங்களுடன் இங்கு இருப்பது மிக்க மகிழ்ச்சி! அமைவுச் செயல்முறையில் நாங்கள் உங்களுக்கு வழிகாட்டுவோம் – சில கேள்விகளுக்கான உங்கள் பதில்கள், உங்கள் கடைக்கான பணம் செலுத்தும் அமைப்புகளைப் பரிந்துரைக்க எங்களுக்கு உதவும்.','What type of products or services do you sell?' => 'நீங்கள் என்ன வகையான பொருட்கள் அல்லது சேவைகளை விற்கிறீர்கள்?','Who do you predominantly sell to?' => 'நீங்கள் பிரதானமாக யாருக்கு விற்பனை செய்கிறீர்கள்?','Where are your customers located?' => 'உங்கள் வாடிக்கையாளர்கள் எங்கே இருக்கிறார்கள்?','Help improve Fluid Checkout with optional usage tracking (no customer data).' => 'விருப்பத்திற்கேற்ப பயன்பாட்டைக் கண்காணிக்கும் வசதியுடன் (வாடிக்கையாளர் தரவு இல்லாமல்) Fluid Checkout-ஐ மேம்படுத்த உதவுங்கள்.','You can review and change this anytime under Tools → Usage tracking.' => 'கருவிகள் → பயன்பாட்டைக் கண்காணித்தல் என்பதன் கீழ் இதை நீங்கள் எப்போது வேண்டுமானாலும் சரிபார்த்து மாற்றிக்கொள்ளலாம்.','Email address' => 'மின்னஞ்சல் முகவரி','Newsletter opt-in' => 'செய்திமடல் விருப்பத்தேர்வு','Opt-in to receive news about new features, tips and recommendations from the Fluid Checkout team directly in your inbox.' => 'புதிய அம்சங்கள், குறிப்புகள் மற்றும் பரிந்துரைகள் குறித்த செய்திகளை Fluid Checkout குழுவிடமிருந்து நேரடியாக உங்கள் இன்பாக்ஸில் பெற விருப்பம் தெரிவியுங்கள்.','What do you sell, and how do you deliver physical products?' => 'நீங்கள் என்னென்ன விற்கிறீர்கள், மற்றும் பொருட்களை எவ்வாறு விநியோகிக்கிறீர்கள்?','What do you sell?' => 'நீங்கள் என்ன விற்கிறீர்கள்?','How do you handle delivery of your products?' => 'உங்கள் தயாரிப்புகளின் விநியோகத்தை எவ்வாறு கையாளுகிறீர்கள்?','Recommended checkout settings' => 'பரிந்துரைக்கப்பட்ட செக்அவுட் அமைப்புகள்','No more recommendations to apply.' => 'விண்ணப்பிப்பதற்கு இனி பரிந்துரைகள் இல்லை.','Show already applied' => 'ஏற்கனவே விண்ணப்பித்ததைக் காட்டு','Based on what you told us, these checkout options are a good starting point. You can turn recommended options off before applying them.' => 'நீங்கள் எங்களிடம் கூறியதன் அடிப்படையில், இந்தப் பணம் செலுத்தும் தெரிவுகள் ஒரு நல்ல தொடக்கமாக அமையும். பரிந்துரைக்கப்பட்ட தெரிவுகளைப் பயன்படுத்துவதற்கு முன்பு நீங்கள் அவற்றை முடக்கலாம்.','You can change any of these settings later in the Fluid Checkout settings.' => 'இந்த அமைப்புகளில் எதையும் நீங்கள் பின்னர் Fluid Checkout அமைப்புகளில் மாற்றிக்கொள்ளலாம்.','Apply settings & finish setup' => 'அமைப்புகளைப் பயன்படுத்தவும் &amp; அமைப்பை முடிக்கவும்','Your recommended setup options have been applied.' => 'நீங்கள் பரிந்துரைத்த அமைவு விருப்பங்கள் செயல்படுத்தப்பட்டுள்ளன.','Test your checkout process and return to Fluid Checkout settings to adjust any settings if needed.' => 'உங்கள் செக்அவுட் செயல்முறையைச் சோதித்துவிட்டு, தேவைப்பட்டால் அமைப்புகளைச் சரிசெய்ய Fluid Checkout அமைப்புகளுக்குத் திரும்பவும்.','You can use the built-in live preview in settings to see how settings changes affect your checkout before saving them.' => 'அமைப்புகளில் நீங்கள் செய்யும் மாற்றங்களைச் சேமிப்பதற்கு முன்பு, அவை உங்கள் செக்அவுட்டை எவ்வாறு பாதிக்கின்றன என்பதைப் பார்க்க, அமைப்புகளில் உள்ள உள்ளமைக்கப்பட்ட நேரடி முன்னோட்டத்தைப் பயன்படுத்தலாம்.','If you need help, <a href="%s" target="_blank" rel="noopener noreferrer">contact our support team</a>.' => 'உங்களுக்கு உதவி தேவைப்பட்டால், <a href="%s" target="_blank" rel="noopener noreferrer">எங்கள் ஆதரவுக் குழுவைத் தொடர்பு கொள்ளுங்கள்</a> .','Subscription account creation' => 'சந்தா கணக்கு உருவாக்கம்','Allow subscription customers to create an account during checkout' => 'சந்தாதாரர் வாடிக்கையாளர்கள் பணம் செலுத்தும் போது கணக்கை உருவாக்க அனுமதிக்கவும்.','Enable account creation at checkout for subscription purchases when account creation for other orders is disabled.' => 'மற்ற ஆர்டர்களுக்குக் கணக்கு உருவாக்கம் முடக்கப்பட்டிருக்கும்போது, சந்தா வாங்குதல்களுக்குப் பணம் செலுத்தும் நேரத்தில் கணக்கு உருவாக்கத்தை இயக்கவும்.','Multi-step checkout' => 'பல-படி சரிபார்ப்பு','Clear steps with few fields at a time to guide customers through checkout and keep them focused.' => 'வாடிக்கையாளர்களுக்குப் பணம் செலுத்தும் செயல்முறையை வழிகாட்டி, அவர்களின் கவனத்தை ஒருமுகப்படுத்த, ஒரு நேரத்தில் சில புலங்களைக் கொண்ட தெளிவான வழிமுறைகள்.','Single-step checkout' => 'ஒற்றை-படி சரிபார்ப்பு','Show all fields at once. Ideal for short checkouts such as digital products or services that don\'t require much information.' => 'அனைத்து புலங்களையும் ஒரே நேரத்தில் காண்பிக்கவும். அதிக தகவல்கள் தேவைப்படாத டிஜிட்டல் தயாரிப்புகள் அல்லது சேவைகள் போன்ற குறுகிய பரிவர்த்தனைகளுக்கு இது மிகவும் ஏற்றது.','Keep theme header and footer' => 'தலைப்பு மற்றும் அடிக்குறிப்பை ஒரே கருப்பொருளில் வைக்கவும்','Show the store header and footer at checkout instead of the distraction-free layout. Useful for B2B stores that need site navigation during checkout.' => 'பணம் செலுத்தும் நேரத்தில், கவனச்சிதறல் இல்லாத தளவமைப்பிற்குப் பதிலாக கடையின் தலைப்பு மற்றும் அடிக்குறிப்பைக் காண்பிக்கவும். பணம் செலுத்தும் நேரத்தில் தள வழிசெலுத்தல் தேவைப்படும் B2B கடைகளுக்கு இது பயனுள்ளதாக இருக்கும்.','Edit cart at checkout' => 'பணம் செலுத்தும் இடத்தில் வண்டியைத் திருத்தவும்','Let customers change quantities and remove items without leaving checkout.' => 'வாடிக்கையாளர்கள் செக்-அவுட்டை விட்டு வெளியேறாமலேயே, பொருட்களின் அளவுகளை மாற்றவும் அவற்றை அகற்றவும் அனுமதிக்கவும்.','Billing before shipping' => 'அனுப்புவதற்கு முன் பில்லிங்','Collect the billing address as a step before shipping so business buyers can enter invoice details first.' => 'வணிகப் பரிவர்த்தனையாளர்கள் முதலில் விலைப்பட்டியல் விவரங்களை உள்ளிடுவதற்காக, அனுப்புவதற்கு முந்தைய ஒரு படியாக பில்லிங் முகவரியைச் சேகரிக்கவும்.','Shipping methods before address' => 'முகவரிக்கு முன் அனுப்பும் முறைகள்','Show shipping methods before the address so customers can see other delivery options such as local pickup.' => 'முகவரிக்கு முன் விநியோக முறைகளைக் காண்பிக்கவும், இதன் மூலம் வாடிக்கையாளர்கள் உள்ளூர் பிக்கப் போன்ற பிற விநியோக விருப்பங்களைக் காண முடியும்.','Shipping methods after address' => 'முகவரிக்குப் பிறகு அனுப்பும் முறைகள்','Ask for the shipping address first, then show shipping methods that match that destination.' => 'முதலில் அனுப்ப வேண்டிய முகவரியைக் கேளுங்கள், பிறகு அந்த இடத்திற்குப் பொருத்தமான அனுப்பும் முறைகளைக் காட்டுங்கள்.','Require billing company' => 'பில்லிங் நிறுவனம் தேவை','Make the billing company field required so invoices include a company name for business orders.' => 'வணிக ஆர்டர்களுக்கான இன்வாய்ஸ்களில் நிறுவனத்தின் பெயர் இடம்பெற, பில்லிங் நிறுவனப் புலத்தைக் கட்டாயமாக்குங்கள்.','Hide additional order notes' => 'கூடுதல் ஆர்டர் குறிப்புகளை மறைக்கவும்','Hide the additional order notes field to keep checkout shorter. Customers rarely need it for most orders.' => 'பணம் செலுத்தும் செயல்முறையை எளிதாக்க, கூடுதல் ஆர்டர் குறிப்புகள் புலத்தை மறைக்கவும். பெரும்பாலான ஆர்டர்களுக்கு வாடிக்கையாளர்களுக்கு இது அரிதாகவே தேவைப்படும்.','Enable optimized cart page' => 'உகந்த வண்டிப் பக்கத்தை இயக்கு','Improved cart page to reduce cart abandonment rates and give customers a consistent experience.' => 'வண்டியைப் பாதியில் கைவிடும் விகிதங்களைக் குறைக்கவும், வாடிக்கையாளர்களுக்கு ஒரு சீரான அனுபவத்தை வழங்கவும் வண்டிப் பக்கம் மேம்படுத்தப்பட்டுள்ளது.','Enable optimized thank you page' => 'மேம்படுத்தப்பட்ட நன்றிப் பக்கத்தை இயக்கு','Improved thank you page to give customers a consistent experience.' => 'வாடிக்கையாளர்களுக்கு சீரான அனுபவத்தை வழங்கும் வகையில் நன்றிப் பக்கம் மேம்படுத்தப்பட்டுள்ளது.','Enable optimized order pay page' => 'மேம்படுத்தப்பட்ட ஆர்டர் கட்டணப் பக்கத்தை இயக்கவும்','Improved order pay page to give customers a consistent experience.' => 'வாடிக்கையாளர்களுக்கு சீரான அனுபவத்தை வழங்கும் வகையில், ஆர்டர் கட்டணம் செலுத்தும் பக்கம் மேம்படுத்தப்பட்டுள்ளது.','Suggest verified addresses as customers type to reduce typos and failed deliveries.' => 'தட்டச்சுப் பிழைகளையும் விநியோகத் தவறுகளையும் குறைப்பதற்காக, வாடிக்கையாளர்கள் தட்டச்சு செய்யும்போது சரிபார்க்கப்பட்ட முகவரிகளைப் பரிந்துரைக்கவும்.','Address book at checkout' => 'பணம் செலுத்தும் இடத்தில் முகவரிப் புத்தகம்','Let logged-in customers pick a saved address instead of retyping it every time.' => 'உள்நுழைந்த வாடிக்கையாளர்கள் ஒவ்வொரு முறையும் முகவரியை மீண்டும் தட்டச்சு செய்வதற்குப் பதிலாக, சேமிக்கப்பட்ட முகவரியைத் தேர்ந்தெடுக்கட்டும்.','Let customers place orders without creating an account first.' => 'வாடிக்கையாளர்கள் முதலில் கணக்கை உருவாக்காமலேயே ஆர்டர்களைச் செய்யட்டும்.','Require account to checkout' => 'பணம் செலுத்த கணக்கு தேவை','Turn off guest checkout so customers must log in or create an account before placing an order.' => 'விருந்தினர் செக்அவுட்டை முடக்கவும், இதன் மூலம் வாடிக்கையாளர்கள் ஆர்டர் செய்வதற்கு முன்பு உள்நுழையவோ அல்லது ஒரு கணக்கை உருவாக்கவோ வேண்டும்.','Login reminder at checkout' => 'பணம் செலுத்தும் போது உள்நுழைவு நினைவூட்டல்','Offer a login link at checkout so returning customers can reuse saved details faster.' => 'பணம் செலுத்தும் இடத்தில் ஒரு உள்நுழைவு இணைப்பை வழங்குங்கள், இதன் மூலம் மீண்டும் வரும் வாடிக்கையாளர்கள் சேமித்த விவரங்களை விரைவாக மீண்டும் பயன்படுத்திக்கொள்ளலாம்.','Account matching at checkout' => 'செக் அவுட்டில் கணக்குப் பொருத்தம்','Detect when the email already belongs to an account and prompt the customer to log in instead of creating a duplicate.' => 'மின்னஞ்சல் ஏற்கனவே ஒரு கணக்கிற்குச் சொந்தமானது என்பதைக் கண்டறிந்து, நகல் மின்னஞ்சலுக்குப் பதிலாக வாடிக்கையாளரை உள்நுழையுமாறு அறிவுறுத்தவும்.','Local pickup or in-store collection' => 'உள்ளூரில் பெற்றுக்கொள்ளலாம் அல்லது கடையில் நேரடியாகப் பெற்றுக்கொள்ளலாம்.','Let customers choose at checkout where to pick up their order.' => 'வாடிக்கையாளர்கள் பணம் செலுத்தும் இடத்தில், தங்கள் ஆர்டரை எங்கு பெற்றுக்கொள்ள வேண்டும் என்பதைத் தேர்வு செய்ய அனுமதிக்கவும்.','Optional shipping phone' => 'விருப்பத்தேர்வு ஷிப்பிங் தொலைபேசி','Show a shipping phone field customers can fill when carriers or delivery partners need a contact number.' => 'சரக்கு அனுப்புநர்கள் அல்லது விநியோகப் பங்காளர்களுக்குத் தொடர்பு எண் தேவைப்படும்போது வாடிக்கையாளர்கள் நிரப்பக்கூடிய ஒரு சரக்குத் தொலைபேசிப் புலத்தைக் காண்பிக்கவும்.','Require shipping phone' => 'அனுப்புவதற்கான தொலைபேசி தேவை','Require a phone number on the shipping address for delivery coordination and failed-delivery recovery.' => 'விநியோக ஒருங்கிணைப்பு மற்றும் விநியோகத் தோல்விக்கான மீட்புக்காக, அனுப்பும் முகவரியில் ஒரு தொலைபேசி எண் தேவைப்படுகிறது.','International phone fields' => 'சர்வதேச தொலைபேசி புலங்கள்','Show country-aware phone inputs so customers can enter numbers in the correct international format.' => 'வாடிக்கையாளர்கள் சரியான சர்வதேச வடிவத்தில் எண்களை உள்ளிடுவதற்கு ஏதுவாக, நாடு வாரியான தொலைபேசி உள்ளீடுகளைக் காண்பிக்கவும்.','One per saved address' => 'சேமிக்கப்பட்ட ஒவ்வொரு முகவரிக்கும் ஒன்று','Button label for applying coupon codesApply' => 'விண்ணப்பிக்கவும்','Checkout step titleContact' => 'தொடர்பு','Checkout step titleShipping' => 'கப்பல் போக்குவரத்து','Checkout step titleBilling' => 'பில்லிங்','Checkout step titlePayment' => 'பணம் செலுத்துதல்','Checkout substep change link labelChange' => 'மாற்றம்','Checkout substep save link labelSave changes' => 'மாற்றங்களைச் சேமிக்கவும்','Substep review textNone.' => 'இல்லை.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'எந்தப் படமும் தேர்ந்தெடுக்கப்படவில்லை.','Settings sectionCart' => 'வண்டியில்','Settings sectionOrder pay' => 'ஆர்டர் ஊதியம்','Settings sectionThank you' => 'நன்றி','Settings section titleIntegrations' => 'ஒருங்கிணைப்புகள்','Settings section titleLicense keys' => 'உரிம விசைகள்','Captcha positionBefore place order section' => 'ஆர்டர் செய்வதற்கு முன் பிரிவு','Captcha positionBefore place order button' => 'ஆர்டர் செய்வதற்கு முன் பொத்தான்','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'மூடு','Log in link label at checkout contact stepLog in' => 'உள்நுழைய','Log in separator label at for when guest checkout is disabledOr continue below' => 'அல்லது கீழே தொடரவும்','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'அல்லது விருந்தினராகத் தொடரவும்','Clear image selection on admin pages.Remove image' => 'படத்தை அகற்று','shipping packagesShipping %d' => 'அனுப்புதல் %d','shipping packagesShipping' => 'கப்பல் போக்குவரத்து','Used as fallback for "Proceed to next step" button labelnext step' => 'அடுத்த கட்டம்','Substep review checkbox valueYes' => 'ஆம்','Substep review checkbox line%1$s: %2$s' => '%1$s: %2$s','Dummy customer first name in the admin previewJohn' => 'ஜான்','Dummy customer last name in the admin previewDoe' => 'பெண் மான்','Dummy customer company in the admin previewExample Company' => 'உதாரண நிறுவனம்','Dummy customer street address in the admin preview123 Main Street' => '123 மெயின் ஸ்ட்ரீட்','Dummy customer city in the admin previewAnytown' => 'எனிடவுன்','Dummy order notes in the admin previewPlease leave the package at the front door.' => 'தயவுசெய்து பொட்டலத்தை முன் வாசலில் வைத்துவிட்டுச் செல்லவும்.','Dummy product name in the admin previewBeanie' => 'பீனி','Dummy product name in the admin previewCap' => 'தொப்பி','Dummy product name in the admin previewT-Shirt' => 'டி-ஷர்ட்','Dummy order update in the admin previewWe received your order and will send you an update when it ships.' => 'உங்கள் ஆர்டரைப் பெற்றுக்கொண்டோம். அது அனுப்பப்படும்போது உங்களுக்குத் தகவல் அனுப்புவோம்.','Dummy download in the admin previewUser guide' => 'பயனர் வழிகாட்டி','Google Places API versionsP